        ctx.fill();
        ctx.fillStyle = '#3f3a31';
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * TAU;
          ctx.beginPath();
          ctx.ellipse(x + Math.cos(a) * 16, y + Math.sin(a) * 7, 3, 2, a, 0, TAU);
          ctx.fill();
        }
        ctx.fillStyle = 'rgba(180, 170, 150, 0.18)';
        ctx.beginPath();
        ctx.ellipse(x, y, 8, 3, 0, 0, TAU);
        ctx.fill();
        break;
      }
      case 'rubble': {
        ctx.fillStyle = '#4b473d';
        for (let i = 0; i < 4; i++) {
          const a = i * 1.9 + h;
          ctx.beginPath();
          ctx.ellipse(x + Math.cos(a) * 10, y + Math.sin(a) * 5, 4, 3, a, 0, TAU);
          ctx.fill();
        }
        break;
      }
      case 'reeds': {
        ctx.strokeStyle = 'rgba(126, 138, 92, 0.6)';
        ctx.lineWidth = 1.4;
        for (let i = 0; i < 4; i++) {
          const rx = x - 8 + i * 5;
          const rh = 10 + hash2(p.tx, p.ty, i) * 10;
          ctx.beginPath();
          ctx.moveTo(rx, y + 2);
          ctx.quadraticCurveTo(rx + sway, y - rh * 0.6, rx + sway * 1.4, y - rh);
          ctx.stroke();
        }
        break;
      }
    }
  }

  drawHighlight(ctx, prop, cam, time) {
    const x = prop.x - cam.x;
    const y = prop.y - cam.y;
    ctx.strokeStyle = `rgba(227, 180, 107, ${0.45 + Math.sin(time * 4) * 0.15})`;
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 5]);
    ctx.beginPath();
    ctx.ellipse(x, y + 2, 22, 9, 0, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
  }
}

import { TAU, clamp, dist, angleTo, angleDiff, hash2 } from './util.js';

export const WEAPONS = {
  fists: { name: 'Bare hands', short: 'HANDS', dmg: 6, range: 50, arc: 1.5, cd: 0.42, stamina: 5, type: 'blunt', knock: 60 },
  axe: { name: 'Hand axe', short: 'AXE', dmg: 15, range: 60, arc: 1.65, cd: 0.62, stamina: 12, type: 'slash', knock: 110 },
  spear: { name: 'Flint spear', short: 'SPEAR', dmg: 12, range: 92, arc: 0.8, cd: 0.55, stamina: 10, type: 'pierce', knock: 80 },
  torch: { name: 'Torch', short: 'TORCH', dmg: 7, range: 58, arc: 1.3, cd: 0.5, stamina: 7, type: 'fire', knock: 50 },
};

export class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.radius = 13;
    this.maxHp = 100;
    this.hp = 100;
    this.hunger = 100;
    this.maxStamina = 100;
    this.stamina = 100;
    this.speed = 208;
    this.facing = -Math.PI / 2;
    this.weapon = 'fists';
    this.owned = { axe: false, spear: false, torch: false };
    this.inventory = { wood: 0, stone: 0, fiber: 0, flint: 0, berry: 2, meat: 0, bandage: 0, shard: 0 };
    this.attackCd = 0;
    this.attackAnim = 0;
    this.swingDir = 0;
    this.dodgeT = 0;
    this.dodgeCd = 0;
    this.invuln = 0;
    this.hurtT = 0;
    this.walkT = 0;
    this.staminaDelay = 0;
    this.dodgeDir = { x: 0, y: 0 };
    this.moving = false;
    this.stepDust = 0;
  }

  get weaponDef() { return WEAPONS[this.weapon]; }

  update(dt, input, world, game) {
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.attackAnim = Math.max(0, this.attackAnim - dt * 4.2);
    this.dodgeCd = Math.max(0, this.dodgeCd - dt);
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtT = Math.max(0, this.hurtT - dt);
    this.staminaDelay = Math.max(0, this.staminaDelay - dt);

    let ix = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    let iy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    const len = Math.hypot(ix, iy);
    if (len > 0) { ix /= len; iy /= len; }
    this.moving = len > 0;

    if (this.dodgeT > 0) {
      this.dodgeT -= dt;
      const sp = 560 * (0.55 + this.dodgeT * 1.6);
      world.moveEntity(this, this.dodgeDir.x * sp * dt, this.dodgeDir.y * sp * dt);
      game.spawnDust(this.x, this.y, 1);
      return;
    }

    if (input.dodge && this.dodgeCd <= 0 && this.stamina > 14) {
      this.dodgeT = 0.22;
      this.dodgeCd = 0.62;
      this.invuln = 0.3;
      this.stamina -= 16;
      this.staminaDelay = 0.5;
      const a = len > 0 ? Math.atan2(iy, ix) : this.facing;
      this.dodgeDir = { x: Math.cos(a), y: Math.sin(a) };
      game.memory.counters.dodges++;
      game.audio.sfx('dodge');
      game.spawnDust(this.x, this.y, 4);
      return;
    }

    const sprint = input.sprint && this.stamina > 2 && len > 0;
    const speed = this.speed * (sprint ? 1.48 : 1);
    if (sprint) {
      this.stamina = Math.max(0, this.stamina - 21 * dt);
      this.staminaDelay = 0.6;
    }
    this.walkT += dt * (sprint ? 13 : 9) * (len > 0 ? 1 : 0);

    if (len > 0) {
      world.moveEntity(this, ix * speed * dt, iy * speed * dt);
      this.stepDust -= dt;
      if (sprint && this.stepDust <= 0) {
        this.stepDust = 0.11;
        game.spawnDust(this.x, this.y + 6, 1);
      }
    }

    if (this.staminaDelay <= 0 && !sprint) {
      this.stamina = Math.min(this.maxStamina, this.stamina + 26 * dt);
    }

    if (this.hunger <= 0) {
      this.hp -= 1.6 * dt;
      if (this.hp <= 0) game.die('Starved in a valley that had nothing left to give');
    } else {
      this.hunger = Math.max(0, this.hunger - 0.62 * dt);
      if (this.hunger > 55 && this.hp < this.maxHp) this.hp = Math.min(this.maxHp, this.hp + 0.42 * dt);
    }
  }

  draw(ctx, cam, time, game) {
    const x = this.x - cam.x;
    const y = this.y - cam.y;
    const bob = this.moving ? Math.sin(this.walkT) * 1.6 : Math.sin(time * 2) * 0.6;
    const bobY = y + bob;

    ctx.fillStyle = 'rgba(0,0,0,0.34)';
    ctx.beginPath();
    ctx.ellipse(x + 2, y + 7, 15, 6, 0, 0, TAU);
    ctx.fill();

    if (this.invuln > 0) {
      ctx.strokeStyle = `rgba(200, 220, 200, ${0.25 + Math.sin(time * 30) * 0.15})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(x, y - 4, 20, 0, TAU);
      ctx.stroke();
    }

    const hurt = this.hurtT > 0 ? `rgba(210, 80, 60, ${this.hurtT * 2})` : null;

    // cloak
    ctx.save();
    ctx.translate(x, bobY - 5);
    ctx.rotate(this.facing + Math.PI / 2);
    ctx.fillStyle = hurt || '#2e3a34';
    ctx.beginPath();
    ctx.moveTo(0, -14);
    ctx.quadraticCurveTo(15, -4, 12, 13);
    ctx.quadraticCurveTo(0, 19, -12, 13);
    ctx.quadraticCurveTo(-15, -4, 0, -14);
    ctx.fill();
    ctx.fillStyle = hurt || '#3c4b42';
    ctx.beginPath();
    ctx.moveTo(-8, -2);
    ctx.quadraticCurveTo(-2, 4, -6, 15);
    ctx.lineTo(-12, 12);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#c8a367';
    ctx.fillRect(-9, 5, 18, 3);
    ctx.restore();

    // hood / head
    ctx.fillStyle = hurt || '#22302b';
    ctx.beginPath();
    ctx.arc(x, bobY - 19, 9, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#d8c6a4';
    ctx.beginPath();
    ctx.arc(x + Math.cos(this.facing) * 3, bobY - 19 + Math.sin(this.facing) * 2, 4.2, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(20, 24, 20, 0.7)';
    ctx.beginPath();
    ctx.arc(x + Math.cos(this.facing) * 4.4, bobY - 20 + Math.sin(this.facing) * 2.4, 1.6, 0, TAU);
    ctx.fill();

    // weapon
    const wd = this.weaponDef;
    const swing = this.attackAnim;
    const dir = swing > 0 ? this.swingDir + (swing - 0.5) * wd.arc * 1.6 : this.facing;
    if (this.weapon !== 'fists') {
      const hx = x + Math.cos(dir) * 12;
      const hy = bobY - 8 + Math.sin(dir) * 7;
      const tipX = x + Math.cos(dir) * (12 + wd.range * 0.55);
      const tipY = bobY - 8 + Math.sin(dir) * (7 + wd.range * 0.4);
      ctx.strokeStyle = this.weapon === 'torch' ? '#5a4227' : '#8a7147';
      ctx.lineWidth = this.weapon === 'axe' ? 3 : 2.5;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(hx, hy);
      ctx.lineTo(tipX, tipY);
      ctx.stroke();
      if (this.weapon === 'axe') {
        ctx.fillStyle = '#9aa0a0';
        ctx.beginPath();
        ctx.ellipse(tipX, tipY, 5, 8, dir, 0, TAU);
        ctx.fill();
      } else if (this.weapon === 'spear') {
        ctx.fillStyle = '#c9c4b2';
        ctx.beginPath();
        ctx.moveTo(tipX + Math.cos(dir) * 7, tipY + Math.sin(dir) * 7);
        ctx.lineTo(tipX + Math.cos(dir + 1.5) * 3, tipY + Math.sin(dir + 1.5) * 3);
        ctx.lineTo(tipX + Math.cos(dir - 1.5) * 3, tipY + Math.sin(dir - 1.5) * 3);
        ctx.closePath();
        ctx.fill();
      } else if (this.weapon === 'torch') {
        const f = Math.sin(time * 12) * 2;
        ctx.fillStyle = 'rgba(240, 160, 60, 0.3)';
        ctx.beginPath();
        ctx.arc(tipX, tipY, 20, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#f0a34e';
        ctx.beginPath();
        ctx.arc(tipX, tipY - 2, 5 + f * 0.2, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#ffe3a0';
        ctx.beginPath();
        ctx.arc(tipX, tipY - 2, 2.4, 0, TAU);
        ctx.fill();
      }
    }

    if (swing > 0.12) {
      ctx.strokeStyle = this.weapon === 'torch'
        ? `rgba(240, 150, 60, ${swing * 0.5})`
        : `rgba(236, 226, 200, ${swing * 0.3})`;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(x, bobY - 8, wd.range * 0.72, this.swingDir - wd.arc * 0.7, this.swingDir + wd.arc * 0.7);
      ctx.stroke();
    }

    if (this.weapon === 'torch') {
      const flick = 0.85 + Math.sin(time * 11) * 0.08;
      ctx.fillStyle = `rgba(255, 190, 110, ${0.05 * flick})`;
      ctx.beginPath();
      ctx.arc(x, bobY - 8, 90, 0, TAU);
      ctx.fill();
    }
  }
}

const ENEMY_BASE = {
  wolf: {
    name: 'Wolf', hp: 38, speed: 206, dmg: 8, range: 36, sight: 330, windup: 0.36,
    cd: 0.85, radius: 14, xp: 1, color: '#4a453c',
  },
  hollow: {
    name: 'Hollow', hp: 64, speed: 126, dmg: 13, range: 46, sight: 420, windup: 0.52,
    cd: 1.15, radius: 15, xp: 2, color: '#3a3730',
  },
  warden: {
    name: 'Warden', hp: 190, speed: 92, dmg: 22, range: 62, sight: 470, windup: 0.78,
    cd: 1.5, radius: 24, xp: 5, color: '#4a4436',
  },
};

export class Enemy {
  constructor(type, x, y, game, opts = {}) {
    const base = ENEMY_BASE[type];
    this.type = type;
    this.x = x;
    this.y = y;
    this.spawnX = x;
    this.spawnY = y;
    this.hp = base.hp;
    this.maxHp = base.hp;
    this.speed = base.speed;
    this.dmg = base.dmg;
    this.range = base.range;
    this.sight = base.sight;
    this.windupTime = base.windup;
    this.cdTime = base.cd;
    this.radius = base.radius;
    this.base = base;
    this.name = base.name;
    this.traits = game.activeTraits;
    this.guard = opts.guard || null;
    this.state = 'wander';
    this.aggro = false;
    this.windup = 0;
    this.cd = 0;
    this.flash = 0;
    this.attackAnim = 0;
    this.wanderT = 0;
    this.wanderTarget = { x, y };
    this.facing = Math.random() * TAU;
    this.vx = 0;
    this.vy = 0;
    this.orbit = (Math.random() < 0.5 ? -1 : 1) * (0.5 + Math.random() * 0.7);
    this.orbitT = 0;
    this.stuckT = 0;
    this.stuckX = x;
    this.stuckY = y;
    this.dead = false;
    this.spawnT = 0;
    this.douseT = 0;
    this.emberEyes = false;
    this.fireResist = 0;
    this.slashResist = 0;
    this.feint = false;
    this.douseFires = false;
    this.lunge = false;
    this.elite = false;
    this.scale = 1;

    this.applyTraits();
    this.hp = this.maxHp;
  }

  applyTraits() {
    const t = this.traits;
    const has = (id) => t.includes(id);
    const count = t.length;

    this.maxHp = Math.round(this.maxHp * (1 + count * 0.055) * (1 + (this.type === 'warden' ? 0.15 : 0)));
    this.dmg = this.dmg * (1 + count * 0.035);

    if (has('emberhide')) { this.fireResist = 0.62; this.emberEyes = true; this.elite = true; }
    if (has('longreach')) { this.speed *= 1.09; this.range += 12; this.lunge = true; this.elite = true; }
    if (has('feint')) { this.feint = true; this.elite = true; }
    if (has('pursuit')) { this.speed *= 1.12; this.sight *= 1.28; this.elite = true; }
    if (has('nightborn')) { this.nightborn = true; this.elite = true; }
    if (has('ashen')) { this.douseFires = true; this.elite = true; }
    if (has('packmind') && this.type === 'wolf') { this.speed *= 1.06; this.packmind = true; this.elite = true; }
    if (has('thickhide')) { this.slashResist = 0.45; this.elite = true; }
    if (has('apex')) { this.maxHp *= 1.18; this.dmg *= 1.08; this.elite = true; }
    if (has('blooddebt')) { this.sight *= 1.22; this.elite = true; }

    if (this.type === 'warden') { this.speed *= 1 + count * 0.015; this.range += 4; }
  }

  update(dt, game) {
    const player = game.player;
    const world = game.world;
    this.spawnT += dt;
    this.flash = Math.max(0, this.flash - dt * 4);
    this.attackAnim = Math.max(0, this.attackAnim - dt * 4);
    this.cd = Math.max(0, this.cd - dt);
    this.windup = Math.max(0, this.windup - dt);

    if (this.vx || this.vy) {
      world.moveEntity(this, this.vx * dt, this.vy * dt);
      this.vx *= Math.pow(0.02, dt);
      this.vy *= Math.pow(0.02, dt);
    }

    const pd = dist(this.x, this.y, player.x, player.y);
    const nightBonus = this.nightborn && game.isNight ? 1.16 : 1;
    const speed = this.speed * nightBonus;

    if (!this.aggro && pd < this.sight && !player.dead) {
      this.aggro = true;
      this.state = 'chase';
      if (this.spawnT > 1) game.enemyAlert(this);
    }

    if (this.aggro && pd > this.sight * 1.9) {
      this.aggro = false;
      this.state = 'wander';
    }

    // Ashen enemies douse fires
    if (this.douseFires && game.isNight) {
      let fire = null;
      for (const p of game.world.props) {
        if (p.type === 'campfire' && p.lit && dist(this.x, this.y, p.x, p.y) < 250) { fire = p; break; }
      }
      if (fire) {
        const fd = dist(this.x, this.y, fire.x, fire.y);
        if (fd < 34) {
          this.douseT += dt;
          if (this.douseT > 0.9) {
            fire.lit = false;
            fire.doused = true;
            this.douseT = 0;
            game.toast('A campfire hisses out. Something learned to hate the light.', 'warn');
            game.audio.sfx('douse');
          }
          return;
        } else if (fd < 260) {
          this.state = 'douse';
          this.moveToward(fire.x, fire.y, speed * 1.05, dt, world);
          return;
        }
      }
    }

    // avoid fire unless warden / ashen
    let fireFear = null;
    if (!this.douseFires && this.type !== 'warden') {
      for (const p of game.world.props) {
        if (p.type === 'campfire' && p.lit) {
          const fd = dist(this.x, this.y, p.x, p.y);
          if (fd < 120) { fireFear = p; break; }
        }
      }
    }

    if (this.state === 'windup') {
      if (this.feint) this.facing = angleTo(this.x, this.y, player.x, player.y);
      if (this.windup <= 0) {
        const strikeRange = this.range + 18;
        if (dist(this.x, this.y, player.x, player.y) < strikeRange) {
          game.damagePlayer(this.dmg * nightBonus, this);
          this.attackAnim = 1;
        }
        this.state = 'recover';
        this.cd = this.cdTime;
        this.recoverT = 0.24;
      }
      return;
    }

    if (this.state === 'recover') {
      this.recoverT -= dt;
      if (this.recoverT <= 0) this.state = this.aggro ? 'chase' : 'wander';
      return;
    }

    if (this.aggro && !player.dead) {
      const a = angleTo(this.x, this.y, player.x, player.y);
      this.facing = a;
      this.orbitT += dt;
      if (pd < this.range + 6 && this.cd <= 0) {
        this.state = 'windup';
        this.windup = this.windupTime * (this.feint ? 1.55 : 1);
        game.audio.sfx(this.type === 'wolf' ? 'snarl' : 'growl');
        return;
      }
      if (pd < this.range * 0.9) {
        // back off slightly to keep attack range
        const back = this.type === 'warden' ? 0.2 : 0.55;
        this.moveToward(player.x - Math.cos(a) * 20, player.y - Math.sin(a) * 20, speed * back, dt, world, true);
      } else {
        let targetA = a;
        if (this.type === 'wolf' && pd > 100) targetA = a + Math.sin(this.orbitT * 1.7) * 0.5 * this.orbit;
        if (this.packmind) targetA += Math.sin(this.orbitT * 2.2) * 0.22;
        const lunge = this.lunge && pd > 130 && pd < 260 && Math.sin(this.orbitT * 3) > 0.94;
        this.moveToward(
          player.x - Math.cos(targetA) * (this.range * 0.7),
          player.y - Math.sin(targetA) * (this.range * 0.7),
          speed * (lunge ? 1.7 : 1),
          dt, world
        );
      }
      // separation
      for (const other of game.enemies) {
        if (other === this || other.dead) continue;
        const d = dist(this.x, this.y, other.x, other.y);
        if (d < this.radius + other.radius + 8 && d > 0.01) {
          const push = (this.radius + other.radius + 8 - d) * 0.5;
          world.moveEntity(this, ((this.x - other.x) / d) * push, ((this.y - other.y) / d) * push);
        }
      }
      return;
    }

    // wander
    this.wanderT -= dt;
    if (this.wanderT <= 0) {
      this.wanderT = 2 + Math.random() * 3;
      const a = Math.random() * TAU;
      const r = 20 + Math.random() * 70;
      this.wanderTarget = { x: this.spawnX + Math.cos(a) * r, y: this.spawnY + Math.sin(a) * r };
    }
    const wd = dist(this.x, this.y, this.wanderTarget.x, this.wanderTarget.y);
    if (wd > 6) {
      this.facing = angleTo(this.x, this.y, this.wanderTarget.x, this.wanderTarget.y);
      this.moveToward(this.wanderTarget.x, this.wanderTarget.y, speed * 0.3, dt, world);
    }
  }

  moveToward(tx, ty, speed, dt, world, slow = false) {
    const a = angleTo(this.x, this.y, tx, ty);
    let dx = Math.cos(a) * speed * dt;
    let dy = Math.sin(a) * speed * dt;
    if (slow) { dx *= 0.6; dy *= 0.6; }
    const beforeX = this.x, beforeY = this.y;
    world.moveEntity(this, dx, dy);
    if (Math.abs(this.x - beforeX) < 0.01 && Math.abs(this.y - beforeY) < 0.01) {
      // slide along obstacle
      world.moveEntity(this, Math.cos(a + Math.PI / 2) * speed * dt, Math.sin(a + Math.PI / 2) * speed * dt);
      if (this.x === beforeX && this.y === beforeY) {
        world.moveEntity(this, Math.cos(a - Math.PI / 2) * speed * dt, Math.sin(a - Math.PI / 2) * speed * dt);
      }
    }
  }

  takeDamage(amount, type, game, knock = 0, fromAngle = 0) {
    if (this.dead) return 0;
    let dmg = amount;
    if (type === 'fire') dmg *= 1 - this.fireResist;
    if (type === 'slash') dmg *= 1 - this.slashResist;
    dmg = Math.max(1, Math.round(dmg));
    this.hp -= dmg;
    this.flash = 1;
    this.aggro = true;
    if (this.state === 'wander') this.state = 'chase';
    if (knock) {
      this.vx += Math.cos(fromAngle) * knock;
      this.vy += Math.sin(fromAngle) * knock;
    }
    game.spawnBlood(this.x, this.y, type === 'fire' ? 'fire' : 'blood', Math.min(9, 2 + dmg * 0.25));
    if (this.hp <= 0) {
      this.dead = true;
      game.onEnemyKilled(this);
    }
    return dmg;
  }

  draw(ctx, cam, time, game) {
    const x = this.x - cam.x;
    const y = this.y - cam.y;
    const isNight = game.isNight;

    ctx.fillStyle = 'rgba(0,0,0,0.32)';
    ctx.beginPath();
    ctx.ellipse(x + 2, y + 6, this.radius + 5, (this.radius + 5) * 0.4, 0, 0, TAU);
    ctx.fill();

    const hurt = this.flash > 0.35;
    ctx.save();
    ctx.translate(x, y - 3);
    ctx.rotate(this.facing + Math.PI / 2);

    if (this.type === 'wolf') {
      const run = Math.sin(time * 12 + this.x) * 2;
      ctx.strokeStyle = hurt ? '#d9a08f' : '#2e2b26';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(-7, 6); ctx.lineTo(-9, 14 + run * 0.4);
      ctx.moveTo(7, 6); ctx.lineTo(9, 14 - run * 0.4);
      ctx.moveTo(-4, -8); ctx.lineTo(-6, -1 + run * 0.3);
      ctx.moveTo(5, -8); ctx.lineTo(7, -1 - run * 0.3);
      ctx.stroke();
      ctx.fillStyle = hurt ? '#d9a08f' : this.emberEyes ? '#4a3a2c' : this.base.color;
      ctx.beginPath();
      ctx.ellipse(0, 0, 11, 18, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = hurt ? '#e8b6a4' : this.emberEyes ? '#5a4532' : '#575047';
      ctx.beginPath();
      ctx.ellipse(0, -14, 8, 9, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = hurt ? '#e8b6a4' : this.emberEyes ? '#5a4532' : '#575047';
      ctx.beginPath();
      ctx.moveTo(-7, -19); ctx.lineTo(-4, -26); ctx.lineTo(-1, -18); ctx.closePath();
      ctx.moveTo(7, -19); ctx.lineTo(4, -26); ctx.lineTo(1, -18); ctx.closePath();
      ctx.fill();
      ctx.fillStyle = this.emberEyes ? '#f3a24a' : isNight ? '#e8b567' : '#c9a25c';
      ctx.beginPath();
      ctx.arc(-3, -17, 1.7, 0, TAU);
      ctx.arc(3, -17, 1.7, 0, TAU);
      ctx.fill();
      if (this.emberEyes) {
        ctx.fillStyle = 'rgba(240, 140, 50, 0.2)';
        ctx.beginPath();
        ctx.arc(0, -16, 10, 0, TAU);
        ctx.fill();
      }
      ctx.strokeStyle = hurt ? '#e8b6a4' : '#3a352e';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, 15); ctx.quadraticCurveTo(6, 24, 2, 28);
      ctx.stroke();
    } else if (this.type === 'hollow') {
      const bob = Math.sin(time * 4 + this.x) * 1;
      ctx.fillStyle = hurt ? '#d9a08f' : '#2f2c27';
      ctx.beginPath();
      ctx.moveTo(0, -14);
      ctx.quadraticCurveTo(14, -4, 11, 15);
      ctx.quadraticCurveTo(0, 20, -11, 15);
      ctx.quadraticCurveTo(-14, -4, 0, -14);
      ctx.fill();
      ctx.fillStyle = hurt ? '#e8b6a4' : '#3b372f';
      ctx.beginPath();
      ctx.arc(0, -16 + bob, 8, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#171512';
      ctx.beginPath();
      ctx.arc(0, -16 + bob, 6, 0, TAU);
      ctx.fill();
      ctx.fillStyle = this.emberEyes ? '#f09a4a' : '#b9c0a0';
      ctx.beginPath();
      ctx.arc(-2.4, -17 + bob, 1.4, 0, TAU);
      ctx.arc(2.4, -17 + bob, 1.4, 0, TAU);
      ctx.fill();
      const sw = this.attackAnim;
      ctx.strokeStyle = '#8b7350';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(9, 2);
      ctx.lineTo(9 + Math.cos(sw * 2) * 22, 2 - 14 + Math.sin(sw * 2) * 6);
      ctx.stroke();
      ctx.fillStyle = '#b9b4a3';
      ctx.beginPath();
      ctx.ellipse(9 + Math.cos(sw * 2) * 24, -12 + Math.sin(sw * 2) * 6, 2.5, 6, 0.4, 0, TAU);
      ctx.fill();
    } else if (this.type === 'warden') {
      const bob = Math.sin(time * 2 + this.x) * 1.5;
      ctx.fillStyle = hurt ? '#d9a08f' : '#3d382e';
      ctx.beginPath();
      ctx.ellipse(0, 4, 20, 25, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = hurt ? '#e8b6a4' : '#4c463a';
      ctx.beginPath();
      ctx.ellipse(-10, -8 + bob, 8, 12, -0.3, 0, TAU);
      ctx.ellipse(10, -8 + bob, 8, 12, 0.3, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#2b2822';
      ctx.beginPath();
      ctx.arc(0, -18 + bob, 11, 0, TAU);
      ctx.fill();
      ctx.fillStyle = this.emberEyes ? '#ffb05a' : '#7fd0b0';
      ctx.beginPath();
      ctx.arc(0, -18 + bob, 4.5, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(127, 208, 176, 0.16)';
      ctx.beginPath();
      ctx.arc(0, -18 + bob, 16, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = hurt ? '#e8b6a4' : '#2f2b24';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-14, 18); ctx.lineTo(-17, 28);
      ctx.moveTo(14, 18); ctx.lineTo(17, 28);
      ctx.stroke();
      ctx.strokeStyle = '#6b5b3e';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(16, -2);
      ctx.lineTo(16 + Math.cos(this.attackAnim * 2) * 30, 12 + Math.sin(this.attackAnim * 2) * 10);
      ctx.stroke();
    }
    ctx.restore();

    if (this.state === 'windup') {
      const p = 1 - this.windup / (this.windupTime * (this.feint ? 1.55 : 1));
      ctx.strokeStyle = `rgba(201, 96, 77, ${0.25 + p * 0.45})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(x, y - 4, this.range + 8, this.facing - 0.45, this.facing + 0.45);
      ctx.stroke();
      ctx.strokeStyle = `rgba(201, 96, 77, ${0.1 + p * 0.2})`;
      ctx.beginPath();
      ctx.arc(x, y - 4, this.radius + 6 + p * 8, 0, TAU);
      ctx.stroke();
    }

    if (this.hp < this.maxHp) {
      const w = 34;
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(x - w / 2, y - this.radius - 26, w, 3);
      ctx.fillStyle = this.type === 'warden' ? '#c9604d' : '#c98a5a';
      ctx.fillRect(x - w / 2, y - this.radius - 26, w * clamp(this.hp / this.maxHp, 0, 1), 3);
    }
    if (this.elite) {
      ctx.fillStyle = 'rgba(227, 180, 107, 0.65)';
      ctx.font = '8px ui-sans-serif, system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(this.traitLabel || 'ADAPTED', x, y - this.radius - 32);
    }
  }
}

export class NPC {
  constructor(key, name, x, y, robe, accent) {
    this.key = key;
    this.name = name;
    this.x = x;
    this.y = y;
    this.homeX = x;
    this.homeY = y;
    this.robe = robe;
    this.accent = accent;
    this.facing = Math.random() * TAU;
    this.radius = 13;
    this.hp = 90;
    this.maxHp = 90;
    this.fleeT = 0;
    this.wanderT = 0;
    this.wanderTarget = { x, y };
    this.hurtT = 0;
    this.dead = false;
    this.solid = true;
  }

  update(dt, game) {
    this.hurtT = Math.max(0, this.hurtT - dt);
    const p = game.player;
    const d = dist(this.x, this.y, p.x, p.y);
    if (this.fleeT > 0) {
      this.fleeT -= dt;
      const a = Math.atan2(this.y - p.y, this.x - p.x);
      game.world.moveEntity(this, Math.cos(a) * 160 * dt, Math.sin(a) * 160 * dt);
      this.facing = a;
      return;
    }
    if (d < 150) {
      this.facing = Math.atan2(p.y - this.y, p.x - this.x);
      return;
    }
    this.wanderT -= dt;
    if (this.wanderT <= 0) {
      this.wanderT = 3 + Math.random() * 4;
      const a = Math.random() * TAU;
      this.wanderTarget = {
        x: this.homeX + Math.cos(a) * 50,
        y: this.homeY + Math.sin(a) * 40,
      };
    }
    if (dist(this.x, this.y, this.wanderTarget.x, this.wanderTarget.y) > 8) {
      const a = Math.atan2(this.wanderTarget.y - this.y, this.wanderTarget.x - this.x);
      this.facing = a;
      game.world.moveEntity(this, Math.cos(a) * 38 * dt, Math.sin(a) * 38 * dt);
    }
  }

  takeDamage(amount, game, fromAngle) {
    this.hp -= amount;
    this.hurtT = 1;
    this.fleeT = 6;
    game.memory.counters.npcHits++;
    game.spawnBlood(this.x, this.y, 'blood', 5);
    if (this.hp <= 0 && !this.dead) {
      this.dead = true;
      game.onNpcKilled(this);
    }
  }

  draw(ctx, cam, time, game) {
    const x = this.x - cam.x;
    const y = this.y - cam.y;
    const bob = Math.sin(time * 2.2 + this.homeX) * 0.8;
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(x + 1, y + 6, 14, 5, 0, 0, TAU);
    ctx.fill();
    ctx.save();
    ctx.translate(x, y - 4 + bob);
    ctx.rotate(this.facing + Math.PI / 2);
    ctx.fillStyle = this.hurtT > 0 ? '#d9a08f' : this.robe;
    ctx.beginPath();
    ctx.moveTo(0, -14);
    ctx.quadraticCurveTo(14, -4, 11, 14);
    ctx.quadraticCurveTo(0, 18, -11, 14);
    ctx.quadraticCurveTo(-14, -4, 0, -14);
    ctx.fill();
    ctx.fillStyle = this.accent;
    ctx.fillRect(-8, 4, 16, 3);
    ctx.fillStyle = this.hurtT > 0 ? '#e8b6a4' : '#c9b391';
    ctx.beginPath();
    ctx.arc(0, -19, 7.5, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#2a2620';
    ctx.beginPath();
    ctx.arc(0, -21, 7.5, Math.PI, TAU);
    ctx.fill();
    ctx.restore();

    ctx.font = '9px ui-sans-serif, system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(227, 180, 107, 0.8)';
    ctx.fillText(this.name.toUpperCase(), x, y - 36);
    if (this.hp < this.maxHp) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(x - 15, y - 31, 30, 2.5);
      ctx.fillStyle = '#c9604d';
      ctx.fillRect(x - 15, y - 31, 30 * clamp(this.hp / this.maxHp, 0, 1), 2.5);
    }
  }
}

import { World, WORLD_SIZE, TILE } from './world.js';
import { Player, Enemy, NPC, WEAPONS } from './entities.js';
import {
  activeTraits, worldSeed, saveMemory, recordDeath, recordVictory, noteRun,
  npcGiftFor, npcAlive, campAbandoned, traitById, addChronicle,
} from './memory.js';
import { clamp, lerp, dist, angleTo, angleDiff, TAU, hash2, roman } from './util.js';

export const DAY_LENGTH = 210;

export const RECIPES = [
  { id: 'axe', name: 'Hand axe', glyph: '⟁', cost: { wood: 3, stone: 2 }, desc: 'Fell trees in fewer swings. Slash damage. Heavy in the hand.' },
  { id: 'spear', name: 'Flint spear', glyph: '⇈', cost: { wood: 3, flint: 1, fiber: 1 }, desc: 'Reach without closeness. The valley learns distance from it.' },
  { id: 'torch', name: 'Torch', glyph: '✧', cost: { wood: 2, fiber: 2 }, desc: 'Light, warmth, and fire damage. Fire leaves permanent scars.' },
  { id: 'bandage', name: 'Bandage', glyph: '✚', cost: { fiber: 3 }, desc: 'Bind a wound. Restores 35 life. Carry as many as you dare.' },
  { id: 'campfire', name: 'Campfire', glyph: '△', cost: { wood: 5, stone: 4 }, desc: 'A circle of safety — until the valley learns to smother it.' },
];

export class Game {
  constructor(canvas, ui, memory, audio) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.ui = ui;
    this.memory = memory;
    this.audio = audio;
    this.state = 'title';
    this.paused = false;
    this.dpr = 1;
    this.w = 0;
    this.h = 0;
    this.activeTraits = activeTraits(memory);
    this.day = 1;
    this.timeOfDay = 0.78;
    this.shards = 0;
    this.enemies = [];
    this.npcs = [];
    this.particles = [];
    this.floaters = [];
    this.ambient = [];
    this.campfires = [];
    this.spawnTimer = 0;
    this.shake = 0;
    this.saveTimer = 0;
    this.uiTimer = 0;
    this.focus = null;
    this.mouse = { x: 0, y: 0, active: false, down: false };
    this.touch = { active: false, dx: 0, dy: 0 };
    this.input = { up: false, down: false, left: false, right: false, sprint: false, dodge: false };
    this.learned = { fire: 0, slash: 0, pierce: 0, blunt: 0 };
    this.adaptToast = 0;
    this.fleeAccum = 0;
    this.fledThisRun = false;
    this.titleT = 0;
    this.deathTimer = 0;
    this.pendingDeath = null;
    this.frame = 0;

    this.lightCanvas = document.createElement('canvas');
    this.lightCtx = this.lightCanvas.getContext('2d');

    this.world = new World(worldSeed(memory), memory);
    this.player = new Player(this.world.spawn.x, this.world.spawn.y);
    this.camera = { x: this.world.camp.x, y: this.world.camp.y + 80 };
    this.spawnNpcs();
    this.resize();
    this.bindInput();
    this.ui.bind(this);

    window.addEventListener('resize', () => this.resize());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.paused = true;
    });

    this.last = performance.now();
    requestAnimationFrame((t) => this.loop(t));
  }

  /* ---------------- lifecycle ---------------- */

  resize() {
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    this.canvas.width = Math.floor(this.w * this.dpr);
    this.canvas.height = Math.floor(this.h * this.dpr);
    this.canvas.style.width = this.w + 'px';
    this.canvas.style.height = this.h + 'px';
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.lightCanvas.width = Math.floor(this.w * this.dpr);
    this.lightCanvas.height = Math.floor(this.h * this.dpr);
    this.lightCtx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  }

  bindInput() {
    const keys = new Set();
    const setKey = (e, down) => {
      const k = e.key.toLowerCase();
      if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' ', 'tab'].includes(k)) e.preventDefault();
      if (down && e.repeat) return;
      if (k === 'w' || k === 'arrowup') this.input.up = down;
      else if (k === 's' || k === 'arrowdown') this.input.down = down;
      else if (k === 'a' || k === 'arrowleft') this.input.left = down;
      else if (k === 'd' || k === 'arrowright') this.input.right = down;
      else if (k === 'shift') this.input.sprint = down;
      else if (k === ' ') { if (down) this.input.dodge = true; }
      else if (down && k === 'e') this.interact();
      else if (down && k === 'c') this.ui.toggleCraft(this);
      else if (down && k === 'm') this.ui.toggleMemory(this.memory);
      else if (down && k === 'escape') this.ui.closeAll();
      else if (down && k === '1') this.equip('axe');
      else if (down && k === '2') this.equip('spear');
      else if (down && k === '3') this.equip('torch');
      else if (down && k === '4') this.eat();
      else if (down && k === '5') this.bandage();
      else if (down && k === 'p') this.audio.toggleMute();
      if (down) keys.add(k); else keys.delete(k);
    };
    window.addEventListener('keydown', (e) => setKey(e, true));
    window.addEventListener('keyup', (e) => setKey(e, false));

    window.addEventListener('mousemove', (e) => {
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
      this.mouse.active = true;
    });
    this.canvas.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      this.mouse.down = true;
      this.audio.unlock();
      this.tryAttack();
    });
    window.addEventListener('mouseup', () => { this.mouse.down = false; });
    window.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('touchstart', () => this.audio.unlock(), { passive: true });
  }

  spawnNpcs() {
    this.npcs = [];
    const c = this.world.camp;
    const defs = [
      { key: 'maren', name: 'Maren', x: c.x - 118, y: c.y + 120, robe: '#4a3d52', accent: '#c8a367' },
      { key: 'sable', name: 'Sable', x: c.x + 132, y: c.y + 96, robe: '#3c4536', accent: '#9f7a45' },
      { key: 'pell', name: 'Pell', x: c.x + 8, y: c.y + 168, robe: '#4d4435', accent: '#b9a06a' },
    ];
    for (const d of defs) {
      if (!npcAlive(this.memory, d.key)) continue;
      this.npcs.push(new NPC(d.key, d.name, d.x, d.y, d.robe, d.accent));
    }
  }

  startRun() {
    this.state = 'playing';
    this.paused = false;
    this.player = new Player(this.world.spawn.x, this.world.spawn.y);
    this.day = 1;
    this.timeOfDay = 0.27;
    this.shards = 0;
    this.enemies = [];
    this.particles = [];
    this.floaters = [];
    this.learned = { fire: 0, slash: 0, pierce: 0, blunt: 0 };
    this.spawnTimer = 5;
    this.shake = 0;
    this.fleeAccum = 0;
    this.fledThisRun = false;
    this.activeTraits = activeTraits(this.memory);
    this.world = new World(worldSeed(this.memory), this.memory);
    this.player.x = this.world.spawn.x;
    this.player.y = this.world.spawn.y;
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    this.spawnNpcs();
    this.ui.hideTitle();
    this.ui.hideEnd();
    this.ui.showHud();
    this.ui.updateHUD(this, true);
    this.audio.startAmbient();
    this.audio.setNight(0);
    const abandoned = campAbandoned(this.memory);
    if (abandoned) this.toast('The Worldroot camp is silent. The tents are empty.', 'warn');
    else this.toast(`Day 1. The valley is listening.`, 'good');
    this.applyGifts();
    saveMemory(this.memory);
  }

  applyGifts() {
    let delay = 1800;
    for (const key of ['maren', 'sable', 'pell']) {
      const gift = npcGiftFor(this.memory, key);
      if (!gift) continue;
      for (const [item, n] of Object.entries(gift.items)) this.player.inventory[item] = (this.player.inventory[item] || 0) + n;
      setTimeout(() => { if (this.state === 'playing') this.toast(gift.line, 'good'); }, delay);
      delay += 2400;
    }
  }

  newCycle() {
    this.ui.hideEnd();
    this.ui.closeAll();
    this.world = new World(worldSeed(this.memory), this.memory);
    this.player = new Player(this.world.spawn.x, this.world.spawn.y);
    this.day = 1;
    this.timeOfDay = 0.27;
    this.shards = 0;
    this.enemies = [];
    this.particles = [];
    this.floaters = [];
    this.learned = { fire: 0, slash: 0, pierce: 0, blunt: 0 };
    this.activeTraits = activeTraits(this.memory);
    this.spawnTimer = 6;
    this.spawnNpcs();
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    this.state = 'playing';
    this.paused = false;
    this.ui.showHud();
    this.ui.updateHUD(this, true);
    this.toast(`Cycle ${roman(this.memory.cycles + 1)}. The valley remembers.`, 'good');
    this.applyGifts();
  }

  /* ---------------- loop ---------------- */

  loop(ts) {
    const dt = Math.min(0.05, (ts - this.last) / 1000 || 0.016);
    this.last = ts;
    this.frame++;
    if (!this.paused) this.update(dt);
    this.render(dt);
    requestAnimationFrame((t) => this.loop(t));
  }

  update(dt) {
    if (this.state === 'title') {
      this.titleT += dt;
      this.updateAmbient(dt);
      this.updateParticles(dt);
      return;
    }
    if (this.state !== 'playing') {
      this.updateParticles(dt);
      if (this.state === 'dying') {
        this.deathTimer -= dt;
        if (this.deathTimer <= 0 && this.pendingDeath) {
          this.state = 'dead';
          this.ui.showDeath(this.pendingDeath);
        }
      }
      return;
    }

    this.timeOfDay += dt / DAY_LENGTH;
    if (this.timeOfDay >= 1) {
      this.timeOfDay -= 1;
      this.day++;
      this.memory.counters.daysSurvived = Math.max(this.memory.counters.daysSurvived, this.day);
      this.toast(`Day ${this.day}. ${this.day % 2 === 0 ? 'The valley has grown hungrier.' : 'Something has changed in the trees.'}`, 'good');
      this.audio.sfx('dawn');
      this.save();
    }

    this.updatePlayer(dt);
    for (const e of [...this.enemies]) e.update(dt, this);
    this.enemies = this.enemies.filter((e) => !e.dead);
    for (const n of this.npcs) n.update(dt, this);
    this.npcs = this.npcs.filter((n) => !n.dead);

    this.updateSpawns(dt);
    this.updateAmbient(dt);
    this.updateParticles(dt);
    this.updateCamera(dt);
    this.updatePrompt();
    this.updateAdaptation(dt);

    this.saveTimer -= dt;
    if (this.saveTimer <= 0) { this.saveTimer = 12; this.save(); }
    this.uiTimer -= dt;
    if (this.uiTimer <= 0) { this.uiTimer = 0.08; this.ui.updateHUD(this); }

    this.shake = Math.max(0, this.shake - dt * 26);
    this.audio.setNight(this.dark);
  }

  updatePlayer(dt) {
    const p = this.player;
    if (p.dead) return;

    if (this.mouse.active && !this.touch.active) {
      const sx = p.x - this.camera.x + this.w / 2;
      const sy = p.y - this.camera.y + this.h / 2;
      p.facing = Math.atan2(this.mouse.y - sy, this.mouse.x - sx);
    } else if (this.touch.active) {
      let nearest = null, nd = 240;
      for (const e of this.enemies) {
        const d = dist(p.x, p.y, e.x, e.y);
        if (d < nd) { nd = d; nearest = e; }
      }
      if (nearest) p.facing = angleTo(p.x, p.y, nearest.x, nearest.y);
      else if (this.touch.dx || this.touch.dy) p.facing = Math.atan2(this.touch.dy, this.touch.dx);
    }

    const inp = {
      ...this.input,
      left: this.input.left || this.touch.dx < -0.22,
      right: this.input.right || this.touch.dx > 0.22,
      up: this.input.up || this.touch.dy < -0.22,
      down: this.input.down || this.touch.dy > 0.22,
    };
    if (this.input.dodge) { inp.dodge = true; this.input.dodge = false; }
    p.update(dt, inp, this.world, this);

    if (this.mouse.down && !this.touch.active) this.tryAttack();

    // fleeing is remembered
    let aggroNear = false;
    for (const e of this.enemies) if (e.aggro && dist(p.x, p.y, e.x, e.y) < 340) { aggroNear = true; break; }
    if (aggroNear && this.input.sprint && p.stamina > 1) {
      this.fleeAccum += dt;
      if (this.fleeAccum > 2.2 && !this.fledThisRun) {
        this.fledThisRun = true;
        this.memory.counters.flees++;
        this.toast('You run. The valley learns the shape of your back.', 'warn');
      }
    } else {
      this.fleeAccum = Math.max(0, this.fleeAccum - dt * 0.5);
    }
  }

  updateCamera(dt) {
    const p = this.player;
    const tx = p.x + Math.cos(p.facing) * 26;
    const ty = p.y + Math.sin(p.facing) * 26;
    this.camera.x = lerp(this.camera.x, tx, 1 - Math.pow(0.001, dt));
    this.camera.y = lerp(this.camera.y, ty, 1 - Math.pow(0.001, dt));
    this.clampCamera();
  }

  clampCamera() {
    if (this.w < WORLD_SIZE) this.camera.x = clamp(this.camera.x, this.w / 2, WORLD_SIZE - this.w / 2);
    else this.camera.x = WORLD_SIZE / 2;
    if (this.h < WORLD_SIZE) this.camera.y = clamp(this.camera.y, this.h / 2, WORLD_SIZE - this.h / 2);
    else this.camera.y = WORLD_SIZE / 2;
  }

  updateSpawns(dt) {
    this.spawnTimer -= dt;
    const dark = this.dark;
    const cap = 4 + Math.floor(dark * 6) + Math.min(3, this.activeTraits.length);
    if (this.spawnTimer <= 0) {
      if (dark > 0.22 && this.enemies.length < cap) {
        const pos = this.world.randomWalkableNear(this.player.x, this.player.y, 560, 860, Math.random);
        if (pos && dist(pos.x, pos.y, this.world.camp.x, this.world.camp.y) > 420) {
          const r = Math.random();
          let type = 'wolf';
          if (r > 0.58) type = 'hollow';
          if (r > 0.92 && (this.day > 2 || this.activeTraits.length >= 3)) type = 'warden';
          this.enemies.push(new Enemy(type, pos.x, pos.y, this));
          if (this.activeTraits.includes('packmind') && type === 'wolf' && Math.random() < 0.5) {
            const p2 = this.world.randomWalkableNear(pos.x, pos.y, 40, 100, Math.random);
            if (p2) this.enemies.push(new Enemy('wolf', p2.x, p2.y, this));
          }
          this.audio.sfx('spawn');
        }
        this.spawnTimer = Math.max(1.4, 3.4 - dark * 1.7 - this.activeTraits.length * 0.08);
      } else if (dark < 0.2 && this.enemies.length < 3) {
        const pos = this.world.randomWalkableNear(this.player.x, this.player.y, 700, 1000, Math.random);
        if (pos && dist(pos.x, pos.y, this.world.camp.x, this.world.camp.y) > 500) {
          this.enemies.push(new Enemy('wolf', pos.x, pos.y, this));
        }
        this.spawnTimer = 6;
      } else {
        this.spawnTimer = 2;
      }
    }

    // ruin guardians
    for (const ruin of this.world.ruins) {
      if (!ruin.pedestal || !ruin.pedestal.shard || ruin.triggered) continue;
      if (dist(this.player.x, this.player.y, ruin.x, ruin.y) < 520) {
        ruin.triggered = true;
        const count = 2 + (this.activeTraits.includes('apex') ? 1 : 0);
        for (let i = 0; i < count; i++) {
          const a = (i / count) * TAU + Math.random();
          const pos = this.world.randomWalkableNear(ruin.x + Math.cos(a) * 180, ruin.y + Math.sin(a) * 180, 20, 80, Math.random);
          if (pos) this.enemies.push(new Enemy(i === 0 ? 'warden' : 'hollow', pos.x, pos.y, this, { guard: ruin }));
        }
        this.toast('The ruin wakes. Something has been waiting here a long time.', 'warn');
        this.audio.sfx('warden');
      }
    }
  }

  updateAmbient(dt) {
    // campfire embers and smoke
    for (const p of this.world.campfires || []) {
      if (!p.lit) continue;
      if (Math.random() < dt * 5) {
        this.particles.push({
          x: p.x + (Math.random() - 0.5) * 14, y: p.y - 8,
          vx: (Math.random() - 0.5) * 10, vy: -20 - Math.random() * 26,
          life: 1.4 + Math.random(), max: 2.4, size: 1.5 + Math.random() * 1.5,
          color: Math.random() < 0.4 ? '#f6c96b' : '#e78c3e', kind: 'fire',
        });
      }
      if (Math.random() < dt * 1.6) {
        this.particles.push({
          x: p.x + (Math.random() - 0.5) * 10, y: p.y - 20,
          vx: (Math.random() - 0.5) * 8, vy: -16 - Math.random() * 14,
          life: 2.2 + Math.random() * 1.4, max: 3.6, size: 3 + Math.random() * 3,
          color: 'rgba(120, 116, 106, 0.2)', kind: 'smoke',
        });
      }
    }
    // torch embers
    if (this.state === 'playing' && this.player.weapon === 'torch' && !this.player.dead && Math.random() < dt * 9) {
      const a = this.player.facing;
      this.particles.push({
        x: this.player.x + Math.cos(a) * 30, y: this.player.y - 8 + Math.sin(a) * 20,
        vx: (Math.random() - 0.5) * 12, vy: -18 - Math.random() * 18,
        life: 0.8 + Math.random() * 0.6, max: 1.4, size: 1 + Math.random(),
        color: '#f0a34e', kind: 'fire',
      });
    }
    // fireflies at night
    if (this.dark > 0.4 && this.state !== 'title' && Math.random() < dt * 1.4) {
      const a = Math.random() * TAU, r = 200 + Math.random() * 500;
      this.ambient.push({
        x: this.player.x + Math.cos(a) * r, y: this.player.y + Math.sin(a) * r,
        vx: (Math.random() - 0.5) * 12, vy: (Math.random() - 0.5) * 12,
        life: 4 + Math.random() * 4, max: 8, phase: Math.random() * TAU,
      });
    }
    for (const f of this.ambient) {
      f.x += f.vx * dt; f.y += f.vy * dt;
      f.vx += Math.sin(this.titleT * 2 + f.phase) * dt * 3;
      f.vy += Math.cos(this.titleT * 1.7 + f.phase) * dt * 3;
      f.life -= dt;
    }
    this.ambient = this.ambient.filter((f) => f.life > 0).slice(-90);
    this.titleT += dt;
  }

  updateParticles(dt) {
    for (const p of this.particles) {
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += (p.kind === 'fire' ? -8 : p.kind === 'smoke' ? -2 : 160) * dt;
      p.vx *= Math.pow(0.2, dt);
      p.life -= dt;
    }
    this.particles = this.particles.filter((p) => p.life > 0).slice(-420);
    for (const f of this.floaters) {
      f.y -= 26 * dt;
      f.life -= dt;
    }
    this.floaters = this.floaters.filter((f) => f.life > 0);
  }

  updateAdaptation(dt) {
    const max = Math.max(this.learned.fire, this.learned.slash, this.learned.pierce, this.learned.blunt);
    const level = max / 0.42;
    if (this.adaptToast === 0 && level > 0.33) {
      this.adaptToast = 1;
      this.toast(this.learned.fire > 0.1 ? 'The valley is learning your fire.' : 'They are learning the weight of your swings.', 'warn');
    } else if (this.adaptToast === 1 && level > 0.66) {
      this.adaptToast = 2;
      this.toast('They are watching how you move now.', 'warn');
    } else if (this.adaptToast === 2 && level > 0.94) {
      this.adaptToast = 3;
      this.toast('They know your rhythm. Change it or die.', 'warn');
      this.audio.sfx('learn');
    }
    this.ui.setAdapt(level, this.state === 'playing');
  }

  updatePrompt() {
    if (this.state !== 'playing') { this.focus = null; this.ui.setPrompt('', false); return; }
    const p = this.player;
    let best = null, bestD = 82;
    for (const n of this.npcs) {
      const d = dist(p.x, p.y, n.x, n.y);
      if (d < 92 && d < bestD + 12) { best = { npc: n, kind: 'npc' }; bestD = d; }
    }
    const near = this.world.nearestInteractable(p.x, p.y, 80);
    if (near && (!best || near.dist < bestD)) best = near;
    this.focus = best;
    if (!best) { this.ui.setPrompt('', false); return; }
    if (best.kind === 'npc') this.ui.setPrompt(`Talk to ${best.npc.name}`, true);
    else if (best.kind === 'harvest') {
      const label = this.harvestLabel(best.prop);
      this.ui.setPrompt(label, true);
    } else if (best.kind === 'shard') this.ui.setPrompt('Take the ember shard', true);
    else if (best.kind === 'grave') this.ui.setPrompt('Search the cairn', true);
    else if (best.kind === 'beacon') {
      this.ui.setPrompt(this.shards >= 3 ? 'Kindle the beacon' : `The beacon is cold — ${3 - this.shards} shard${3 - this.shards === 1 ? '' : 's'} missing`, true);
    }
  }

  harvestLabel(prop) {
    if (prop.type === 'tree' || prop.type === 'pine' || prop.type === 'deadtree') return 'Gather wood';
    if (prop.type === 'bush') return 'Gather fiber and berries';
    if (prop.type === 'boulder') return 'Gather stone';
    if (prop.type === 'flint') return 'Gather flint';
    return 'Gather';
  }

  /* ---------------- actions ---------------- */

  tryAttack() {
    if (this.state !== 'playing' || this.paused || this.player.dead) return;
    const p = this.player;
    if (p.attackCd > 0 || p.dodgeT > 0) return;
    const wd = p.weaponDef;
    if (p.stamina < wd.stamina) return;
    p.stamina -= wd.stamina;
    p.staminaDelay = 0.55;
    p.attackCd = wd.cd;
    p.attackAnim = 1;
    p.swingDir = p.facing;
    this.memory.counters.attacks++;
    this.audio.sfx(p.weapon === 'fists' ? 'swing' : p.weapon);
    this.spawnSwing(p);

    let hitSomething = false;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist(p.x, p.y, e.x, e.y);
      if (d > wd.range + e.radius) continue;
      const ad = Math.abs(angleDiff(angleTo(p.x, p.y, e.x, e.y), p.facing));
      if (ad > wd.arc / 2 + 0.12) continue;
      let dmg = wd.dmg;
      if (wd.type === 'fire' && e.type === 'wolf') dmg *= 1.18;
      if (wd.type === 'pierce' && e.type === 'warden') dmg *= 1.22;
      const applied = e.takeDamage(dmg, wd.type, this, wd.knock, p.facing);
      this.learn(wd.type);
      this.memory.counters.hits[wd.type]++;
      this.addFloater(e.x, e.y - e.radius - 14, `-${applied}`, wd.type === 'fire' ? '#f0a34e' : '#e7ddc6');
      hitSomething = true;
    }

    for (const n of this.npcs) {
      if (n.dead) continue;
      const d = dist(p.x, p.y, n.x, n.y);
      if (d > wd.range + n.radius) continue;
      const ad = Math.abs(angleDiff(angleTo(p.x, p.y, n.x, n.y), p.facing));
      if (ad > wd.arc / 2 + 0.12) continue;
      n.takeDamage(wd.dmg, this, p.facing);
      this.addFloater(n.x, n.y - 30, `-${wd.dmg}`, '#c9604d');
      this.shake = 4;
      hitSomething = true;
    }

    if (hitSomething) {
      this.shake = Math.max(this.shake, 4);
      this.audio.sfx('hit');
      this.hitStop = 0.04;
    }

    if (wd.type === 'fire') this.igniteNearby(p, wd);
  }

  igniteNearby(p, wd) {
    const props = this.world.propsNear(p.x, p.y, wd.range + 40);
    for (const prop of props) {
      if (prop.dead) continue;
      if (!['tree', 'pine', 'deadtree'].includes(prop.type)) continue;
      const d = dist(p.x, p.y, prop.x, prop.y);
      if (d > wd.range + 26) continue;
      const ad = Math.abs(angleDiff(angleTo(p.x, p.y, prop.x, prop.y), p.facing));
      if (ad > wd.arc / 2 + 0.4) continue;
      if (Math.random() > 0.4) continue;
      this.world.burnTree(prop);
      this.spawnFire(prop.x, prop.y - 20, 18);
      this.audio.sfx('fire');
      this.memory.counters.harvested += 0;
      if (!this.burnToast) {
        this.burnToast = true;
        this.toast('The tree becomes a scar. The valley will keep it.', 'warn');
      }
      addChronicle(this.memory, { cycle: this.memory.cycles + 1, day: this.day, kind: 'fire', text: `Burned the forest near the ${this.compass(prop.x, prop.y)}.` });
    }
  }

  learn(type) {
    this.learned[type] = Math.min(0.42, this.learned[type] + 0.011);
    // Enemies slowly read the dominant style.
    const total = this.learned.fire + this.learned.slash + this.learned.pierce + this.learned.blunt;
    if (total > 0.9) {
      this.learned[type] = Math.min(0.42, this.learned[type] + 0.002);
    }
  }

  interact() {
    if (this.state !== 'playing' || this.paused || this.player.dead) return;
    const f = this.focus;
    if (!f) return;
    if (f.kind === 'npc') { this.audio.sfx('talk'); this.ui.openDialogue(f.npc, this); return; }
    if (f.kind === 'harvest') { this.harvest(f.prop); return; }
    if (f.kind === 'shard') { this.takeShard(f.prop); return; }
    if (f.kind === 'grave') { this.lootGrave(f.prop); return; }
    if (f.kind === 'beacon') { this.useBeacon(); return; }
  }

  harvest(prop) {
    const p = this.player;
    const axe = p.weapon === 'axe' || p.owned.axe;
    const inv = p.inventory;
    const gain = {};
    if (prop.type === 'tree' || prop.type === 'pine') {
      gain.wood = axe ? 3 : 1;
      this.spawnLeaves(prop.x, prop.y - 40, 10);
    } else if (prop.type === 'deadtree') {
      gain.wood = axe ? 2 : 1;
      this.spawnLeaves(prop.x, prop.y - 30, 6);
    } else if (prop.type === 'bush') {
      gain.fiber = 2;
      if (prop.berry) gain.berry = 1;
      this.spawnLeaves(prop.x, prop.y - 6, 8, '#7d945c');
    } else if (prop.type === 'boulder') {
      gain.stone = axe ? 3 : 2;
      this.spawnDust(prop.x, prop.y, 8);
    } else if (prop.type === 'flint') {
      gain.flint = 2;
      this.spawnDust(prop.x, prop.y, 5);
    }
    for (const [k, v] of Object.entries(gain)) inv[k] = (inv[k] || 0) + v;
    this.memory.counters.harvested++;
    const label = Object.entries(gain).map(([k, v]) => `+${v} ${k}`).join('  ');
    this.addFloater(p.x, p.y - 34, label, '#d9c69a');
    this.audio.sfx('gather');
    prop.charges = (prop.charges ?? 2) - 1;
    if (prop.charges <= 0) {
      this.world.removeProp(prop);
      this.spawnDust(prop.x, prop.y, 10);
    }
    this.ui.updateHUD(this, true);
  }

  takeShard(prop) {
    prop.shard = false;
    const site = this.world.ruins[prop.site];
    if (site) site.taken = true;
    this.shards++;
    this.memory.counters.shards++;
    this.addFloater(this.player.x, this.player.y - 44, 'EMBER SHARD', '#f0c987');
    this.toast(`${this.shards} of 3 shards. The beacon stirs.`, 'good');
    this.audio.sfx('shard');
    this.shake = 6;
    this.spawnFire(prop.x, prop.y - 50, 24);
    this.save();
    this.ui.updateHUD(this, true);
  }

  lootGrave(prop) {
    prop.looted = true;
    if (prop.grave) prop.grave.taken = true;
    const loot = prop.loot || { wood: 2, fiber: 2 };
    const inv = this.player.inventory;
    for (const [k, v] of Object.entries(loot)) {
      if (k === 'weapon') continue;
      inv[k] = (inv[k] || 0) + v;
    }
    if (loot.weapon && !this.player.owned[loot.weapon]) {
      this.player.owned[loot.weapon] = true;
      this.player.weapon = loot.weapon;
    }
    this.addFloater(this.player.x, this.player.y - 36, 'WHAT YOU LEFT BEHIND', '#d9c69a');
    this.toast('You find what the valley left of you. It kept everything.', 'good');
    this.audio.sfx('gather');
    this.save();
    this.ui.updateHUD(this, true);
  }

  useBeacon() {
    if (this.shards < 3) {
      this.toast(`The Worldroot is cold. ${3 - this.shards} shard${3 - this.shards === 1 ? '' : 's'} still sleep in the ruins.`, 'warn');
      return;
    }
    this.win();
  }

  equip(weapon) {
    if (weapon === 'fists') return;
    if (!this.player.owned[weapon]) {
      this.toast(`You have no ${WEAPONS[weapon].name.toLowerCase()} yet.`, 'warn');
      return;
    }
    this.player.weapon = weapon;
    this.audio.sfx('equip');
    this.ui.updateHUD(this, true);
  }

  eat() {
    if (this.state !== 'playing' || this.paused) return;
    const inv = this.player.inventory;
    if (inv.meat > 0) {
      inv.meat--;
      this.player.hunger = Math.min(100, this.player.hunger + 38);
      this.player.hp = Math.min(this.player.maxHp, this.player.hp + 12);
      this.addFloater(this.player.x, this.player.y - 40, 'MEAT +38', '#c9a25c');
      this.audio.sfx('eat');
    } else if (inv.berry > 0) {
      inv.berry--;
      this.player.hunger = Math.min(100, this.player.hunger + 18);
      this.player.hp = Math.min(this.player.maxHp, this.player.hp + 2);
      this.addFloater(this.player.x, this.player.y - 40, 'BERRIES +18', '#c9a25c');
      this.audio.sfx('eat');
    } else {
      this.toast('Nothing to eat. The bushes are bare.', 'warn');
    }
    this.ui.updateHUD(this, true);
  }

  bandage() {
    if (this.state !== 'playing' || this.paused) return;
    const inv = this.player.inventory;
    if (inv.bandage <= 0) { this.toast('No bandages. Three fiber will make one.', 'warn'); return; }
    inv.bandage--;
    this.player.hp = Math.min(this.player.maxHp, this.player.hp + 35);
    this.addFloater(this.player.x, this.player.y - 40, '+35 LIFE', '#8fae7a');
    this.audio.sfx('heal');
    this.ui.updateHUD(this, true);
  }

  craft(id) {
    if (this.state !== 'playing') return false;
    const recipe = RECIPES.find((r) => r.id === id);
    if (!recipe) return false;
    const inv = this.player.inventory;
    for (const [k, v] of Object.entries(recipe.cost)) {
      if ((inv[k] || 0) < v) { this.toast(`Not enough ${k}.`, 'warn'); return false; }
    }
    for (const [k, v] of Object.entries(recipe.cost)) inv[k] -= v;
    this.memory.counters.crafted++;
    if (id === 'bandage') inv.bandage = (inv.bandage || 0) + 1;
    else if (id === 'campfire') {
      const a = this.player.facing;
      let x = this.player.x + Math.cos(a) * 46;
      let y = this.player.y + Math.sin(a) * 46;
      if (this.world.circleBlocked(x, y, 14)) { x = this.player.x; y = this.player.y + 20; }
      const fire = this.world.addCampfire(x, y);
      this.world.campfires.push(fire);
      this.memory.counters.campfireLit++;
      this.memory.ashes.push({ x: Math.round(x), y: Math.round(y) });
      if (this.memory.ashes.length > 16) this.memory.ashes.shift();
      this.spawnFire(x, y - 10, 14);
      this.toast('The fire takes. For a while, the dark keeps its distance.', 'good');
      addChronicle(this.memory, { cycle: this.memory.cycles + 1, day: this.day, kind: 'fire', text: `Made camp near the ${this.compass(x, y)}.` });
    } else {
      this.player.owned[id] = true;
      this.player.weapon = id;
    }
    this.audio.sfx('craft');
    this.ui.updateHUD(this, true);
    this.save();
    return true;
  }

  /* ---------------- combat / consequences ---------------- */

  damagePlayer(amount, source) {
    const p = this.player;
    if (p.dead || p.invuln > 0 || this.state !== 'playing') return;
    p.hp -= amount;
    p.hurtT = 1;
    p.stamina = Math.max(0, p.stamina - 8);
    this.shake = Math.max(this.shake, 7);
    this.audio.sfx('hurt');
    this.spawnBlood(p.x, p.y - 8, 'blood', 7);
    this.addFloater(p.x, p.y - 38, `-${Math.round(amount)}`, '#d98070');
    if (p.hp <= 0) {
      const cause = source
        ? source.type === 'wolf' ? 'Torn apart by the pack'
          : source.type === 'warden' ? 'Broken by a Warden of the ruin'
            : 'Cut down by a Hollow'
        : 'The valley took you';
      this.die(cause);
    }
  }

  onEnemyKilled(e) {
    const c = this.memory.counters;
    c.kills++;
    if (e.type === 'wolf') c.wolfKills++;
    if (e.type === 'hollow') c.hollowKills++;
    if (e.type === 'warden') c.wardenKills++;
    if (this.isNight) c.nightKills++;
    this.spawnBlood(e.x, e.y, 'blood', 16);
    this.spawnDust(e.x, e.y, 10);
    this.audio.sfx('kill');
    if (e.type === 'wolf') this.player.inventory.meat = (this.player.inventory.meat || 0) + 1;
    if (e.type === 'hollow') this.player.inventory.fiber = (this.player.inventory.fiber || 0) + 1;
    if (e.type === 'warden') {
      this.player.inventory.flint = (this.player.inventory.flint || 0) + 2;
      this.shake = 9;
    }
    this.addFloater(e.x, e.y - 30, e.type === 'warden' ? 'WARDEN FALLS' : 'SLAIN', '#d9c69a');
    // live adaptation on kill: enemies get a little bolder
    const dominant = this.dominantStyle();
    if (dominant) this.learned[dominant] = Math.min(0.42, this.learned[dominant] + 0.004);
    this.ui.updateHUD(this, true);
  }

  onNpcKilled(npc) {
    this.memory.npcs[npc.key].alive = false;
    this.memory.counters.npcKills++;
    addChronicle(this.memory, { cycle: this.memory.cycles + 1, day: this.day, kind: 'blood', text: `Killed ${npc.name} at the Worldroot.` });
    this.toast(`${npc.name} is dead. The valley will not forget this.`, 'warn');
    this.spawnBlood(npc.x, npc.y, 'blood', 24);
    this.audio.sfx('death');
    this.save();
  }

  dominantStyle() {
    const l = this.learned;
    let best = null, v = 0.12;
    for (const k of Object.keys(l)) if (l[k] > v) { v = l[k]; best = k; }
    return best;
  }

  die(cause) {
    if (this.state !== 'playing') return;
    const p = this.player;
    p.dead = true;
    p.hp = 0;
    this.state = 'dying';
    this.deathTimer = 1.15;
    this.audio.sfx('death');
    this.audio.stopAmbient();
    this.spawnBlood(p.x, p.y, 'blood', 30);
    this.shake = 14;
    const before = [...activeTraits(this.memory)];
    const loot = { wood: 2, fiber: 2 };
    if (p.weapon !== 'fists') loot.weapon = p.weapon;
    if (p.inventory.flint > 0) loot.flint = 1;
    const cycle = this.memory.cycles + 1;
    recordDeath(this.memory, { day: this.day, cause, x: p.x, y: p.y, cycle, loot });
    const after = activeTraits(this.memory);
    const gained = after.filter((t) => !before.includes(t));
    this.memory.lastRun = {
      kind: 'death', day: this.day, cause, cycle,
      traits: gained, kills: this.memory.counters.kills, at: Date.now(),
    };
    this.memory.counters.daysSurvived = Math.max(this.memory.counters.daysSurvived, this.day);
    saveMemory(this.memory);
    const line = gained.length
      ? 'The valley has learned something new about you.'
      : 'The valley already knew how you would die.';
    this.pendingDeath = {
      cause,
      day: this.day,
      cycle,
      gained,
      line,
      kills: this.memory.counters.kills,
      grave: this.memory.graves[0],
    };
  }

  win() {
    if (this.state !== 'playing') return;
    this.state = 'victory';
    const before = [...activeTraits(this.memory)];
    const cycle = this.memory.cycles + 1;
    recordVictory(this.memory, { day: this.day, cycle, kills: this.memory.counters.kills });
    const after = activeTraits(this.memory);
    const gained = after.filter((t) => !before.includes(t));
    this.memory.counters.daysSurvived = Math.max(this.memory.counters.daysSurvived, this.day);
    saveMemory(this.memory);
    this.audio.sfx('victory');
    this.audio.stopAmbient();
    this.shake = 12;
    this.spawnFire(this.world.beacon.x, this.world.beacon.y - 100, 60);
    this.ui.showVictory({
      day: this.day,
      cycle,
      kills: this.memory.counters.kills,
      gained,
      traits: after,
      line: gained.length
        ? 'It has learned new ways to make the next cycle harder.'
        : 'It already knew you. It will know you better.',
    });
  }

  /* ---------------- effects ---------------- */

  addFloater(x, y, text, color) {
    this.floaters.push({ x, y, text, color: color || '#e7ddc6', life: 1.25, max: 1.25 });
  }

  spawnDust(x, y, n) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      this.particles.push({
        x, y: y + 4, vx: Math.cos(a) * (10 + Math.random() * 30), vy: Math.sin(a) * (8 + Math.random() * 16),
        life: 0.4 + Math.random() * 0.4, max: 0.8, size: 2 + Math.random() * 2.5,
        color: 'rgba(150, 140, 112, 0.45)', kind: 'dust',
      });
    }
  }

  spawnBlood(x, y, kind, n) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = 20 + Math.random() * 90;
      this.particles.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 20,
        life: 0.35 + Math.random() * 0.5, max: 0.85, size: 1.5 + Math.random() * 2.6,
        color: kind === 'fire' ? '#f0a34e' : '#8e3b30', kind: 'blood',
      });
    }
  }

  spawnLeaves(x, y, n, color) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      this.particles.push({
        x, y, vx: Math.cos(a) * (20 + Math.random() * 50), vy: -10 + Math.random() * 20,
        life: 0.8 + Math.random() * 0.9, max: 1.7, size: 2 + Math.random() * 2.5,
        color: color || '#5f7a45', kind: 'leaf',
      });
    }
  }

  spawnFire(x, y, n) {
    for (let i = 0; i < n; i++) {
      this.particles.push({
        x: x + (Math.random() - 0.5) * 30, y: y + (Math.random() - 0.5) * 20,
        vx: (Math.random() - 0.5) * 40, vy: -20 - Math.random() * 60,
        life: 0.6 + Math.random() * 1.1, max: 1.7, size: 2 + Math.random() * 3,
        color: Math.random() < 0.5 ? '#f6c96b' : '#e78c3e', kind: 'fire',
      });
    }
  }

  spawnSwing(p) {
    const wd = p.weaponDef;
    for (let i = 0; i < 4; i++) {
      const a = p.facing + (Math.random() - 0.5) * wd.arc;
      this.particles.push({
        x: p.x + Math.cos(a) * wd.range * 0.7, y: p.y - 8 + Math.sin(a) * wd.range * 0.5,
        vx: Math.cos(a) * 20, vy: Math.sin(a) * 20,
        life: 0.18, max: 0.2, size: 2, color: 'rgba(236, 226, 200, 0.4)', kind: 'dust',
      });
    }
  }

  toast(text, kind) {
    this.ui.toast(text, kind);
  }

  save() {
    if (this.state === 'playing') {
      noteRun(this.memory, {
        day: this.day,
        kills: this.memory.counters.kills,
        traits: this.activeTraits,
        cause: null,
      });
    }
    saveMemory(this.memory);
  }

  compass(x, y) {
    const dx = x - this.world.camp.x, dy = y - this.world.camp.y;
    if (Math.abs(dx) > Math.abs(dy)) return dx > 0 ? 'east' : 'west';
    return dy > 0 ? 'south' : 'north';
  }

  get dark() {
    if (this.timeOfDay < 0.5) return 0;
    return Math.sin((this.timeOfDay - 0.5) * Math.PI);
  }

  get isNight() { return this.dark > 0.3; }

  get phase() {
    const t = this.timeOfDay;
    if (t < 0.11) return 'Dawn';
    if (t < 0.4) return 'Day';
    if (t < 0.52) return 'Dusk';
    if (t < 0.9) return 'Night';
    return 'Dawn';
  }

  /* ---------------- render ---------------- */

  render(dt) {
    const ctx = this.ctx;
    const w = this.w, h = this.h;
    const shakeX = this.shake > 0 ? (Math.random() - 0.5) * this.shake : 0;
    const shakeY = this.shake > 0 ? (Math.random() - 0.5) * this.shake : 0;

    let cam = this.camera;
    if (this.state === 'title') {
      const t = this.titleT;
      cam = {
        x: this.world.camp.x + Math.sin(t * 0.1) * 130,
        y: this.world.camp.y + 40 + Math.cos(t * 0.08) * 60,
      };
      this.clampCameraFor(cam);
    }

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.translate(shakeX, shakeY);

    this.world.drawGround(ctx, cam, w + 40, h + 40, this.titleT);

    const renderables = [];
    for (const p of this.world.visibleProps(cam, w + 80, h + 80)) {
      if (p.type === 'banner') continue;
      renderables.push({ y: p.y + (p.type === 'tree' ? 0 : 0), kind: 'prop', obj: p });
    }
    for (const e of this.enemies) renderables.push({ y: e.y, kind: 'enemy', obj: e });
    for (const n of this.npcs) renderables.push({ y: n.y, kind: 'npc', obj: n });
    if (this.state !== 'title' || true) renderables.push({ y: this.player.y, kind: 'player', obj: this.player });
    renderables.sort((a, b) => a.y - b.y);

    for (const r of renderables) {
      if (r.kind === 'prop') this.world.drawProp(ctx, r.obj, this.titleT, cam);
      else if (r.kind === 'enemy') r.obj.draw(ctx, cam, this.titleT, this);
      else if (r.kind === 'npc') r.obj.draw(ctx, cam, this.titleT, this);
      else r.obj.draw(ctx, cam, this.titleT, this);
    }

    if (this.focus && this.focus.prop && this.state === 'playing') this.world.drawHighlight(ctx, this.focus.prop, cam, this.titleT);

    this.drawParticles(ctx, cam);
    this.drawAmbient(ctx, cam);
    this.drawFloaters(ctx, cam);
    ctx.restore();

    this.drawLighting(ctx, cam, w, h);
    this.drawWeather(ctx, w, h);
  }

  clampCameraFor(cam) {
    if (this.w < WORLD_SIZE) cam.x = clamp(cam.x, this.w / 2, WORLD_SIZE - this.w / 2);
    else cam.x = WORLD_SIZE / 2;
    if (this.h < WORLD_SIZE) cam.y = clamp(cam.y, this.h / 2, WORLD_SIZE - this.h / 2);
    else cam.y = WORLD_SIZE / 2;
  }

  drawParticles(ctx, cam) {
    for (const p of this.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      ctx.globalAlpha = p.kind === 'smoke' ? a * 0.5 : a;
      ctx.fillStyle = p.color;
      if (p.kind === 'leaf') {
        ctx.save();
        ctx.translate(p.x - cam.x, p.y - cam.y);
        ctx.rotate(p.life * 8);
        ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
        ctx.restore();
      } else if (p.kind === 'smoke') {
        ctx.beginPath();
        ctx.arc(p.x - cam.x, p.y - cam.y, p.size * (1.6 - a * 0.6), 0, TAU);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(p.x - cam.x, p.y - cam.y, p.size * a, 0, TAU);
        ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }

  drawAmbient(ctx, cam) {
    for (const f of this.ambient) {
      const a = Math.min(1, f.life) * (0.4 + Math.sin(this.titleT * 4 + f.phase) * 0.3);
      ctx.fillStyle = `rgba(220, 240, 150, ${a})`;
      ctx.beginPath();
      ctx.arc(f.x - cam.x, f.y - cam.y, 1.6, 0, TAU);
      ctx.fill();
      ctx.fillStyle = `rgba(220, 240, 150, ${a * 0.18})`;
      ctx.beginPath();
      ctx.arc(f.x - cam.x, f.y - cam.y, 6, 0, TAU);
      ctx.fill();
    }
  }

  drawFloaters(ctx, cam) {
    ctx.textAlign = 'center';
    for (const f of this.floaters) {
      const a = clamp(f.life / f.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.font = '600 10px ui-sans-serif, system-ui, sans-serif';
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillText(f.text, f.x - cam.x + 1, f.y - cam.y + 1);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x - cam.x, f.y - cam.y);
    }
    ctx.globalAlpha = 1;
  }

  drawLighting(ctx, cam, w, h) {
    const dark = this.state === 'title' ? Math.max(0.55, this.dark) : this.dark;
    if (dark < 0.03) return;
    const lctx = this.lightCtx;
    lctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    lctx.clearRect(0, 0, w, h);
    lctx.fillStyle = `rgba(7, 11, 20, ${0.86 * dark})`;
    lctx.fillRect(0, 0, w, h);

    const lights = [];
    for (const p of this.world.campfires || []) {
      if (p.lit) lights.push({ x: p.x, y: p.y, r: p.radius || 220, warm: 1 });
    }
    if (this.player.weapon === 'torch' && this.state !== 'title') {
      lights.push({ x: this.player.x, y: this.player.y - 6, r: 190, warm: 0.9 });
    }
    if (this.world.beacon) lights.push({ x: this.world.beacon.x, y: this.world.beacon.y - 70, r: 300, warm: 0.8 });
    for (const r of this.world.ruins) {
      if (r.pedestal && r.pedestal.shard) lights.push({ x: r.x, y: r.y - 40, r: 130, warm: 0.6 });
    }
    for (const e of this.enemies) {
      if (e.type === 'warden' && dist(e.x, e.y, cam.x, cam.y) < 900) lights.push({ x: e.x, y: e.y - 18, r: 80, warm: 0.2, cool: true });
    }

    lctx.globalCompositeOperation = 'destination-out';
    for (const l of lights) {
      const sx = l.x - cam.x + w / 2;
      const sy = l.y - cam.y + h / 2;
      if (sx < -l.r || sy < -l.r || sx > w + l.r || sy > h + l.r) continue;
      const g = lctx.createRadialGradient(sx, sy, 0, sx, sy, l.r);
      g.addColorStop(0, 'rgba(0,0,0,0.95)');
      g.addColorStop(0.45, 'rgba(0,0,0,0.6)');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      lctx.fillStyle = g;
      lctx.beginPath();
      lctx.arc(sx, sy, l.r, 0, TAU);
      lctx.fill();
    }
    lctx.globalCompositeOperation = 'source-over';
    ctx.drawImage(this.lightCanvas, 0, 0, w, h);

    // warm additive bloom
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const l of lights) {
      if (l.cool) continue;
      const sx = l.x - cam.x + w / 2;
      const sy = l.y - cam.y + h / 2;
      if (sx < -l.r || sy < -l.r || sx > w + l.r || sy > h + l.r) continue;
      const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, l.r * 0.8);
      const inten = 0.14 * dark * (l.warm || 1);
      g.addColorStop(0, `rgba(255, 176, 88, ${inten})`);
      g.addColorStop(0.5, `rgba(255, 140, 60, ${inten * 0.35})`);
      g.addColorStop(1, 'rgba(255, 120, 40, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(sx, sy, l.r * 0.8, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawWeather(ctx, w, h) {
    if (this.dark < 0.5) return;
    const a = (this.dark - 0.5) * 0.06;
    ctx.fillStyle = `rgba(90, 120, 140, ${a})`;
    ctx.fillRect(0, 0, w, h);
  }
}

import { activeTraits, traitById, forgetMemory, npcGiftFor } from './memory.js';
import { RECIPES } from './game.js';
import { roman, clamp } from './util.js';

const $ = (id) => document.getElementById(id);

const INV_META = {
  wood: { label: 'WOOD', color: '#a07a48' },
  stone: { label: 'STONE', color: '#8f8d80' },
  fiber: { label: 'FIBER', color: '#7d945c' },
  flint: { label: 'FLINT', color: '#b9b4a3' },
  berry: { label: 'BERRY', color: '#b45a4b' },
  meat: { label: 'MEAT', color: '#a85a4a' },
  bandage: { label: 'BIND', color: '#d8c6a4' },
  shard: { label: 'SHARD', color: '#f0c987' },
};

const TRAIT_ORDER = ['emberhide', 'longreach', 'feint', 'pursuit', 'nightborn', 'ashen', 'packmind', 'thickhide', 'apex', 'blooddebt'];

export class UI {
  constructor(memory, audio) {
    this.memory = memory;
    this.audio = audio;
    this.game = null;
    this.toastTimers = new Set();
    this.lastInv = '';
    this.touchMode = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.bindStatic();
  }

  bind(game) {
    this.game = game;
    if (this.touchMode) {
      $('touch').classList.remove('hidden');
      game.touch.active = true;
    }
  }

  bindStatic() {
    $('btn-begin').addEventListener('click', () => {
      this.audio.unlock();
      this.game.startRun();
    });
    $('btn-title-memory').addEventListener('click', () => this.openMemory(this.memory));
    $('btn-mute').addEventListener('click', () => {
      const muted = this.audio.toggleMute();
      $('btn-mute').textContent = muted ? '×' : '♪';
      $('btn-mute').style.opacity = muted ? '0.5' : '1';
    });
    $('btn-memory').addEventListener('click', () => this.toggleMemory(this.memory));
    $('btn-respawn').addEventListener('click', () => this.game.newCycle());
    $('btn-next-cycle').addEventListener('click', () => this.game.newCycle());
    $('btn-forget').addEventListener('click', () => {
      if (!confirm('Forget every death, every lesson, every scar? This cannot be undone.')) return;
      forgetMemory();
      location.reload();
    });
    for (const el of document.querySelectorAll('[data-close]')) {
      el.addEventListener('click', () => this.closeAll());
    }
    $('recipe-grid').addEventListener('click', (e) => {
      const card = e.target.closest('.recipe');
      if (!card) return;
      const id = card.dataset.id;
      if (this.game && this.game.state === 'playing') {
        this.game.craft(id);
        this.openCraft(this.game, true);
      }
    });
    $('weapons').addEventListener('click', (e) => {
      const slot = e.target.closest('.wslot');
      if (slot && this.game) this.game.equip(slot.dataset.w);
    });
    $('dlg-options').addEventListener('click', (e) => {
      const btn = e.target.closest('.dlg-opt');
      if (btn && btn.dataset.act) {
        const fn = this._dlgActions?.[Number(btn.dataset.act)];
        if (fn) fn();
      }
    });
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') this.closeAll();
    });
    this.bindTouch();
  }

  bindTouch() {
    const stick = $('stick');
    const knob = $('stick-knob');
    let id = null;
    const setStick = (e) => {
      const r = stick.getBoundingClientRect();
      let dx = e.clientX - (r.left + r.width / 2);
      let dy = e.clientY - (r.top + r.height / 2);
      const max = r.width / 2 - 14;
      const len = Math.hypot(dx, dy);
      if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      if (this.game) {
        this.game.touch.dx = dx / max;
        this.game.touch.dy = dy / max;
        this.game.touch.active = true;
      }
    };
    stick.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      id = e.pointerId;
      stick.setPointerCapture(id);
      setStick(e);
    });
    stick.addEventListener('pointermove', (e) => {
      if (e.pointerId !== id) return;
      e.preventDefault();
      setStick(e);
    });
    const end = (e) => {
      if (e.pointerId !== id) return;
      id = null;
      knob.style.transform = '';
      if (this.game) { this.game.touch.dx = 0; this.game.touch.dy = 0; }
    };
    stick.addEventListener('pointerup', end);
    stick.addEventListener('pointercancel', end);

    for (const btn of document.querySelectorAll('[data-touch]')) {
      const act = btn.dataset.touch;
      btn.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.audio.unlock();
        if (!this.game) return;
        if (act === 'attack') this.game.touch.attack = true;
        else if (act === 'dodge') this.game.input.dodge = true;
        else if (act === 'interact') this.game.interact();
        else if (act === 'craft') this.toggleCraft(this.game);
        else if (act === 'memory') this.toggleMemory(this.memory);
        else if (act === 'eat') this.game.eat();
      });
      btn.addEventListener('pointerup', (e) => {
        e.preventDefault();
        if (act === 'attack' && this.game) this.game.touch.attack = false;
      });
      btn.addEventListener('pointercancel', () => { if (act === 'attack' && this.game) this.game.touch.attack = false; });
    }
  }

  /* ---------------- screens ---------------- */

  showTitle(memory) {
    const traits = activeTraits(memory);
    const c = memory.counters;
    const deaths = memory.graves.length;
    const titleMemory = $('title-memory');
    if (memory.cycles === 0 && deaths === 0) {
      titleMemory.innerHTML = 'The valley has not learned you yet. <b>Nothing here remembers your name.</b><br>That will change.';
    } else {
      const traitNames = traits.length
        ? traits.map((t) => `<span class="tm-trait">${traitById(t).name}</span>`).join(', ')
        : 'nothing yet';
      titleMemory.innerHTML = `Cycle <b>${roman(memory.cycles + 1)}</b> · <b>${deaths}</b> past ${deaths === 1 ? 'life' : 'lives'} · <b>${c.kills}</b> things killed<br>The valley has learned ${traitNames}.`;
    }
    const chron = $('title-chronicle');
    chron.innerHTML = this.chronicleHTML(memory, 5);
    $('title-seed').textContent = `The valley is listening · seed ${(memory.seedSalt % 9973).toString().padStart(4, '0')}`;
    $('title').classList.remove('hidden');
    $('hud').classList.add('hidden');
    $('touch').classList.add('hidden');
  }

  hideTitle() { $('title').classList.add('hidden'); }
  showHud() {
    $('hud').classList.remove('hidden');
    if (this.touchMode) $('touch').classList.remove('hidden');
  }
  hideEnd() { $('death').classList.add('hidden'); $('victory').classList.add('hidden'); }

  showDeath(summary) {
    $('hud').classList.add('hidden');
    $('touch').classList.add('hidden');
    $('death-cause').textContent = `${summary.cause}. Day ${summary.day}, cycle ${roman(summary.cycle)}.`;
    this.renderTraits($('death-traits'), summary.gained, true);
    $('death-line').textContent = summary.line;
    $('death').classList.remove('hidden');
  }

  showVictory(summary) {
    $('hud').classList.add('hidden');
    $('touch').classList.add('hidden');
    $('victory-text').textContent = `You carried three shards out of the dark and woke the Worldroot on day ${summary.day}. ${summary.kills} things died along the way. The valley watched all of it.`;
    this.renderTraits($('victory-traits'), summary.gained.length ? summary.gained : summary.traits, true);
    $('victory').classList.remove('hidden');
  }

  /* ---------------- panels ---------------- */

  isModalOpen() {
    return ['panel-memory', 'panel-craft', 'dialogue'].some((id) => !$(id).classList.contains('hidden'));
  }

  closeAll() {
    for (const id of ['panel-memory', 'panel-craft', 'dialogue']) $(id).classList.add('hidden');
    if (this.game && this.game.state === 'playing') this.game.paused = false;
  }

  toggleMemory(memory) {
    if (!$( 'panel-memory').classList.contains('hidden')) { this.closeAll(); return; }
    if (this.game && !['playing', 'title', 'dead', 'victory'].includes(this.game.state)) return;
    this.openMemory(memory);
  }

  openMemory(memory) {
    $('panel-craft').classList.add('hidden');
    $('dialogue').classList.add('hidden');
    const traits = activeTraits(memory);
    this.renderTraits($('trait-grid'), traits, false);
    const graves = $('grave-list');
    if (!memory.graves.length) {
      graves.innerHTML = '<p class="chronicle-empty">No cairns yet. The valley is still deciding what you are.</p>';
    } else {
      graves.innerHTML = memory.graves.map((g) => `
        <div class="grave"><b>${g.taken ? 'Cairn emptied' : 'Cairn intact'} · cycle ${roman(g.cycle)}</b><span>DAY ${g.day}</span></div>
        <div class="grave" style="border-top:none;padding-top:0;color:var(--faint)">${g.cause}${g.loot?.weapon ? ' · ' + g.loot.weapon.toUpperCase() + ' left behind' : ''}</div>
      `).join('');
    }
    $('memory-chronicle').innerHTML = this.chronicleHTML(memory, 40);
    const c = memory.counters;
    const stats = [
      ['Cycles lived', memory.cycles],
      ['Best day', memory.bestDay],
      ['Deaths', c.deaths],
      ['Things killed', c.kills],
      ['Wolves killed', c.wolfKills],
      ['Kills at night', c.nightKills],
      ['Shards taken', c.shards],
      ['Fires lit', c.campfireLit],
      ['Trees burned', memory.burns.length],
      ['Crafts made', c.crafted],
      ['Times fled', c.flees],
      ['Dodges', c.dodges],
      ['Maren trust', memory.npcs.maren.trust],
      ['Sable trust', memory.npcs.sable.trust],
      ['Blood spilled', c.npcKills],
      ['Gifts waiting', ['maren', 'sable', 'pell'].filter((k) => npcGiftFor(memory, k)).length],
    ];
    $('memory-stats').innerHTML = stats.map(([k, v]) => `<div class="stat-cell"><span>${k}</span><b>${v}</b></div>`).join('');
    $('panel-memory').classList.remove('hidden');
    if (this.game && this.game.state === 'playing') this.game.paused = true;
  }

  toggleCraft(game) {
    if (!$('panel-craft').classList.contains('hidden')) { this.closeAll(); return; }
    if (!game || game.state !== 'playing') return;
    this.openCraft(game);
  }

  openCraft(game, keepOpen = false) {
    $('panel-memory').classList.add('hidden');
    $('dialogue').classList.add('hidden');
    const inv = game.player.inventory;
    $('recipe-grid').innerHTML = RECIPES.map((r) => {
      const can = Object.entries(r.cost).every(([k, v]) => (inv[k] || 0) >= v);
      const cost = Object.entries(r.cost).map(([k, v]) => `<span class="${(inv[k] || 0) >= v ? 'ok' : 'no'}">${v} ${k}</span>`).join('');
      const owned = r.id !== 'bandage' && r.id !== 'campfire' && game.player.owned[r.id];
      return `<div class="recipe ${can ? '' : 'locked'}" data-id="${r.id}">
        <span class="r-key">${owned ? 'OWNED' : ''}</span>
        <span class="r-glyph">${r.glyph}</span>
        <div class="r-name">${r.name}</div>
        <div class="r-desc">${r.desc}</div>
        <div class="r-cost">${cost}</div>
      </div>`;
    }).join('');
    $('panel-craft').classList.remove('hidden');
    game.paused = true;
    if (keepOpen) game.paused = true;
  }

  /* ---------------- dialogue ---------------- */

  openDialogue(npc, game) {
    this.game = game;
    game.paused = true;
    this._dlgNpc = npc;
    this.renderDialogue(npc, game);
    $('dialogue').classList.remove('hidden');
    this.audio.sfx('talk');
  }

  renderDialogue(npc, game, overrideText) {
    const memory = game.memory;
    const inv = game.player.inventory;
    const c = memory.counters;
    const trust = memory.npcs[npc.key]?.trust || 0;
    $('dlg-portrait').textContent = npc.name[0];
    $('dlg-name').textContent = npc.name;
    const options = [];
    const actions = [];
    const add = (label, disabled, fn) => { options.push({ label, disabled }); actions.push(fn); };

    let text = overrideText;
    if (npc.key === 'maren') {
      if (!text) {
        if (trust >= 40) text = 'You again. The fire is yours. The valley talks about you, you know. Not kindly, always, but it talks.';
        else if (c.deaths > 0) text = 'You have the look of someone the valley has already buried. It kept your things, didn\'t it? It always keeps the things.';
        else text = 'First warm body in a while. Sit. Don\'t waste the fire. The dark out there is older than the ruins.';
      }
      add(`Give 3 berries (${inv.berry || 0}/3)`, (inv.berry || 0) < 3, () => {
        inv.berry -= 3;
        memory.npcs.maren.trust = Math.min(100, trust + 14);
        memory.npcs.maren.quests.berries = true;
        inv.bandage = (inv.bandage || 0) + 2;
        game.toast('Maren takes the berries and presses two bandages into your hand.', 'good');
        game.audio.sfx('talk');
        this.renderDialogue(npc, game, 'The valley gives little and takes much. You gave first. I will remember that, and so will it.');
        this.updateHUD(game, true);
      });
      add('Ask about the beacon', false, () => {
        this.renderDialogue(npc, game, 'The Worldroot was a beacon once. Three ember shards were taken to the ruins — east, north, south of here — and the dark got in. Bring them home and the tree will burn again. The valley will see you do it.');
      });
      add('Ask what the valley remembers', false, () => {
        const traits = activeTraits(memory);
        const list = traits.length ? traits.map((t) => traitById(t).name).join(', ') : 'nothing yet. It is still deciding.';
        this.renderDialogue(npc, game, `It remembers ${list}. Every swing, every fire, every time you ran. It is not cruel. It is only thorough.`);
      });
      add('Leave', false, () => this.closeAll());
    } else if (npc.key === 'sable') {
      if (!text) {
        if (trust >= 40) text = 'The pack circles wider when you are near. They remember your smell. So do I. That is not a bad thing.';
        else if (c.wolfKills > 3) text = `You have killed ${c.wolfKills} of them. They know your weight now. Walk quieter, or walk with fire.`;
        else text = 'You walk loud. The wolves already know how much you weigh. Learn to be less.';
      }
      add(`Give 2 meat (${inv.meat || 0}/2)`, (inv.meat || 0) < 2, () => {
        inv.meat -= 2;
        memory.npcs.sable.trust = Math.min(100, trust + 14);
        memory.npcs.sable.quests.meat = true;
        inv.flint = (inv.flint || 0) + 2;
        game.toast('Sable trades two flint for the meat without a word.', 'good');
        game.audio.sfx('talk');
        this.renderDialogue(npc, game, 'Good. Flint is honest. Meat is honest. Most everything else in this valley lies.');
        this.updateHUD(game, true);
      });
      add('Ask about the pack', false, () => {
        const traits = activeTraits(memory);
        let hint;
        if (traits.includes('emberhide')) hint = 'They roll in the ash now. Your fire bites shallower. Use the spear, or use the dark.';
        else if (traits.includes('thickhide')) hint = 'They are thicker through the shoulder. The axe catches. The spear still finds a way in.';
        else if (traits.includes('feint')) hint = 'They wait for your roll now. Do not roll where you mean to land.';
        else hint = 'They watch your feet more than your hands. Change the rhythm. Hit once, move, hit again.';
        this.renderDialogue(npc, game, hint);
      });
      add('Ask where the shards sleep', false, () => {
