183:             this.addProp('boulder', tx, ty, { solid: true, r: 20, stone: 3 });
184:           } else if (h > 0.935 && h < 0.945) {
185:             this.addProp('tree', tx, ty, { solid: true, r: 12, wood: 3 });
186:           }
187:         } else if (t === TER.SAND) {
188:           if (h < 0.05) this.addProp('reeds', tx, ty, { solid: false });
189:         } else if (t === TER.ROCK) {
190:           if (h < 0.24) this.addProp('flint', tx, ty, { solid: false, flint: 2 });
191:           else if (h > 0.9) this.addProp('boulder', tx, ty, { solid: true, r: 18, stone: 2 });
192:         } else if (t === TER.ASH) {
193:           if (h < 0.06) this.addProp('deadtree', tx, ty, { solid: true, r: 8, wood: 1 });
194:           if (h > 0.93) this.addProp('flint', tx, ty, { solid: false, flint: 1 });
195:         }
196:       }
197:     }
198:   }
199: 
200:   placeCamp() {
201:     const { tx: cx, ty: cy } = this.camp;
202:     const root = this.addProp('worldroot', cx, cy - 3, { solid: true, r: 38, beacon: true, y: (cy - 3 + 0.5) * TILE + 24 });
203:     this.beacon = root;
204:     this.addProp('campfire', cx, cy + 2, { solid: false, lit: true, radius: 230 });
205:     this.addProp('tent', cx - 4, cy + 3, { solid: true, r: 24 });
206:     this.addProp('tent', cx + 4, cy + 4, { solid: true, r: 24 });
207:     this.addProp('crate', cx - 3, cy + 1, { solid: true, r: 11 });
208:     this.addProp('crate', cx + 3, cy + 1, { solid: true, r: 11 });
209:     this.addProp('banner', cx - 6, cy - 2, { solid: false });
210:     this.addProp('banner', cx + 6, cy - 2, { solid: false });
211:     this.addProp('log', cx - 2, cy + 3, { solid: false });
212:     this.addProp('log', cx + 2, cy + 3, { solid: false });
213:     this.addProp('lantern', cx - 5, cy + 1, { solid: true, r: 7, lit: true });
214:     this.addProp('lantern', cx + 5, cy + 1, { solid: true, r: 7, lit: true });
215:     this.addProp('rack', cx - 6, cy + 5, { solid: false });
216:     this.spawn = { x: (cx + 0.5) * TILE, y: (cy + 6.5) * TILE };
217:   }
218: 
219:   placeMemory() {
220:     for (const r of this.ruins) {
221:       const p = this.addProp('pedestal', r.tx, r.ty, { solid: true, r: 13, site: r.index, shard: !r.taken, y: (r.ty + 0.5) * TILE + 18 });
222:       r.pedestal = p;
223:       const n = 7;
224:       for (let i = 0; i < n; i++) {
225:         const a = (i / n) * TAU + 0.3;
226:         if (i === 1 || i === 4) continue;
227:         const px = Math.round(r.tx + Math.cos(a) * 3.6);
228:         const py = Math.round(r.ty + Math.sin(a) * 3.6);
229:         this.addProp('pillar', px, py, { solid: true, r: 15, broken: hash2(px, py, this.seed) < 0.5 });
230:       }
231:       this.addProp('rubble', r.tx + 2, r.ty - 2, { solid: false });
232:       this.addProp('rubble', r.tx - 3, r.ty + 1, { solid: false });
233:     }
234: 
235:     for (const g of this.memory.graves || []) {
236:       const tx = clamp(Math.round(g.x / TILE), 4, this.size - 5);
237:       const ty = clamp(Math.round(g.y / TILE), 4, this.size - 5);
238:       const spot = this.findWalkableNear(tx, ty, 10);
239:       if (!spot) continue;
240:       this.addProp('cairn', spot.tx, spot.ty, {
241:         solid: false,
242:         grave: g,
243:         looted: g.taken,
244:         loot: g.loot,
245:         y: (spot.ty + 0.5) * TILE + 10,
246:       });
247:     }
248: 
249:     for (const a of this.memory.ashes || []) {
250:       const tx = clamp(Math.round(a.x / TILE), 4, this.size - 5);
251:       const ty = clamp(Math.round(a.y / TILE), 4, this.size - 5);
252:       const spot = this.findWalkableNear(tx, ty, 6);
253:       if (spot) this.addProp('ashring', spot.tx, spot.ty, { solid: false });
254:     }
255:   }
256: 
257:   /* ---------------- queries ---------------- */
258: 
259:   propsNear(x, y, radius = 96) {
260:     const out = [];
261:     const r = Math.ceil(radius / TILE) + 1;
262:     const cx = Math.floor(x / TILE), cy = Math.floor(y / TILE);
263:     for (let ty = cy - r; ty <= cy + r; ty++) {
264:       for (let tx = cx - r; tx <= cx + r; tx++) {
265:         const bucket = this.grid.get(`${tx},${ty}`);
266:         if (!bucket) continue;
267:         for (const p of bucket) {
268:           if (p.dead) continue;
269:           if (Math.abs(p.x - x) <= radius + 40 && Math.abs(p.y - y) <= radius + 40) out.push(p);
270:         }
271:       }
272:     }
273:     return out;
274:   }
275: 
276:   solidAtPoint(x, y, radius = 0) {
277:     const t = this.terrainAtPx(x, y);
278:     if (t === TER.WATER || t === TER.ROCK) return true;
279:     if (radius > 0) {
280:       for (let i = 0; i < 8; i++) {
281:         const a = (i / 8) * TAU;
282:         const tt = this.terrainAtPx(x + Math.cos(a) * radius, y + Math.sin(a) * radius);
283:         if (tt === TER.WATER || tt === TER.ROCK) return true;
284:       }
285:     }
286:     return false;
287:   }
288: 
289:   circleBlocked(x, y, radius) {
290:     if (this.solidAtPoint(x, y, radius * 0.8)) return true;
291:     const props = this.propsNear(x, y, radius + 42);
292:     for (const p of props) {
293:       if (!p.solid || p.dead) continue;
294:       const rr = (p.r || 12) * 0.82 + radius;
295:       if (dist(x, y, p.x, p.y - (p.type === 'tree' || p.type === 'pine' ? 8 : 0)) < rr) return true;
296:     }
297:     return false;
298:   }
299: 
300:   moveEntity(ent, dx, dy) {
301:     const r = ent.radius || 13;
302:     if (!this.circleBlocked(ent.x + dx, ent.y, r)) ent.x += dx;
303:     if (!this.circleBlocked(ent.x, ent.y + dy, r)) ent.y += dy;
304:     ent.x = clamp(ent.x, 20, WORLD_SIZE - 20);
305:     ent.y = clamp(ent.y, 20, WORLD_SIZE - 20);
306:   }
307: 
308:   nearestInteractable(x, y, radius = 76) {
309:     let best = null;
310:     let bestD = radius;
311:     for (const p of this.propsNear(x, y, radius)) {
312:       if (p.dead) continue;
313:       let kind = null;
314:       if (p.beacon) kind = 'beacon';
315:       else if (p.type === 'pedestal' && p.shard) kind = 'shard';
316:       else if (p.type === 'cairn' && !p.looted) kind = 'grave';
317:       else if (p.type === 'tree' || p.type === 'pine' || p.type === 'bush' || p.type === 'boulder' || p.type === 'flint' || p.type === 'deadtree') kind = 'harvest';
318:       if (!kind) continue;
319:       const d = dist(x, y, p.x, p.y);
320:       if (d < bestD) { bestD = d; best = { prop: p, kind, dist: d }; }
321:     }
322:     return best;
323:   }
324: 
325:   removeProp(p) {
326:     p.dead = true;
327:   }
328: 
329:   burnTree(p) {
330:     if (p.dead) return;
331:     p.dead = true;
332:     const key = `${p.tx},${p.ty}`;
333:     this.burnSet.add(key);
334:     this.burnPoints.push({ x: p.x, y: p.y });
335:     this.memory.burns = this.memory.burns || [];
336:     this.memory.burns.push({ x: Math.round(p.x), y: Math.round(p.y) });
337:     if (this.memory.burns.length > 400) this.memory.burns.shift();
338:     this.terrain[this.idx(p.tx, p.ty)] = TER.ASH;
339:     const chunk = this.chunks.get(`${Math.floor(p.tx / 12)},${Math.floor(p.ty / 12)}`);
340:     if (chunk) chunk.dirty = true;
341:     this.invalidateChunkAt(p.tx, p.ty);
342:   }
343: 
344:   addCampfire(x, y) {
345:     const p = this.addProp('campfire', Math.floor(x / TILE), Math.floor(y / TILE), {
346:       solid: false, lit: true, radius: 210, built: true, ox: 0, oy: 0,
347:     });
348:     p.x = x; p.y = y;
349:     return p;
350:   }
351: 
352:   randomWalkableNear(x, y, minR, maxR, rng) {
353:     for (let i = 0; i < 40; i++) {
354:       const a = rng() * TAU;
355:       const r = minR + rng() * (maxR - minR);
356:       const px = x + Math.cos(a) * r;
357:       const py = y + Math.sin(a) * r;
358:       if (px < 200 || py < 200 || px > WORLD_SIZE - 200 || py > WORLD_SIZE - 200) continue;
359:       if (this.circleBlocked(px, py, 18)) continue;
360:       return { x: px, y: py };
361:     }
362:     return null;
363:   }
364: 
365:   findWalkableAround(x, y, radius = 600, rng = Math.random) {
366:     for (let i = 0; i < 60; i++) {
367:       const a = rng() * TAU;
368:       const r = 80 + rng() * radius;
369:       const px = x + Math.cos(a) * r;
370:       const py = y + Math.sin(a) * r;
371:       if (px < 80 || py < 80 || px > WORLD_SIZE - 80 || py > WORLD_SIZE - 80) continue;
372:       if (!this.circleBlocked(px, py, 16)) return { x: px, y: py };
373:     }
374:     return { x: this.camp.x, y: this.camp.y + 200 };
375:   }
376: 
377:   /* ---------------- minimap ---------------- */
378: 
379:   buildTerrainBase() {
380:     const px = 4;
381:     const n = this.size * px;
382:     const c = document.createElement('canvas');
383:     c.width = n; c.height = n;
384:     const g = c.getContext('2d');
385:     const img = g.createImageData(n, n);
386:     for (let ty = 0; ty < this.size; ty++) {
387:       for (let tx = 0; tx < this.size; tx++) {
388:         const t = this.terrain[this.idx(tx, ty)];
389:         const col = COLORS[t][0];
390:         const r = parseInt(col.slice(1, 3), 16);
391:         const gg = parseInt(col.slice(3, 5), 16);
392:         const b = parseInt(col.slice(5, 7), 16);
393:         const jitter = (hash2(tx, ty, this.seed + 55) - 0.5) * 4;
394:         for (let oy = 0; oy < px; oy++) {
395:           for (let ox = 0; ox < px; ox++) {
396:             const i = ((ty * px + oy) * n + (tx * px + ox)) * 4;
397:             img.data[i] = clamp(r + jitter, 0, 255);
398:             img.data[i + 1] = clamp(gg + jitter, 0, 255);
399:             img.data[i + 2] = clamp(b + jitter, 0, 255);
400:             img.data[i + 3] = 255;
401:           }
402:         }
403:       }
404:     }
405:     g.putImageData(img, 0, 0);
406:     this.terrainBase = c;
407:   }
408: 
409:   buildGroundNoise() {
410:     const n = 320;
411:     const c = document.createElement('canvas');
412:     c.width = n; c.height = n;
413:     const g = c.getContext('2d');
414:     const img = g.createImageData(n, n);
415:     for (let y = 0; y < n; y++) {
416:       for (let x = 0; x < n; x++) {
417:         const a = fbm(x * 0.055, y * 0.055, 4, this.seed + 701);
418:         const b = fbm(x * 0.17 + 30, y * 0.17 + 70, 3, this.seed + 903);
419:         let v = 118 + (a - 0.5) * 130 + (b - 0.5) * 46;
420:         v = clamp(v, 34, 232);
421:         const i = (y * n + x) * 4;
422:         img.data[i] = v; img.data[i + 1] = v; img.data[i + 2] = v; img.data[i + 3] = 255;
423:       }
424:     }
425:     g.putImageData(img, 0, 0);
426:     this.groundNoise = c;
427:   }
428: 
429:   buildMinimap() {
430:     const c = document.createElement('canvas');
431:     c.width = this.size;
432:     c.height = this.size;
433:     const g = c.getContext('2d');
434:     const img = g.createImageData(this.size, this.size);
435:     for (let y = 0; y < this.size; y++) {
436:       for (let x = 0; x < this.size; x++) {
437:         const t = this.terrain[this.idx(x, y)];
438:         let col;
439:         if (t === TER.WATER) col = [28, 48, 54];
440:         else if (t === TER.SAND) col = [92, 81, 55];
441:         else if (t === TER.FOREST) col = [45, 60, 38];
442:         else if (t === TER.ROCK) col = [64, 62, 55];
443:         else if (t === TER.ASH) col = [46, 42, 37];
444:         else col = [58, 74, 46];
445:         const i = (y * this.size + x) * 4;
446:         img.data[i] = col[0];
447:         img.data[i + 1] = col[1];
448:         img.data[i + 2] = col[2];
449:         img.data[i + 3] = 255;
450:       }
451:     }
452:     g.putImageData(img, 0, 0);
453:     this.minimap = c;
454:   }
455: 
456:   /* ---------------- rendering ---------------- */
457: 
458:   invalidateChunkAt(tx, ty) {
459:     const key = `${Math.floor(tx / 12)},${Math.floor(ty / 12)}`;
460:     const chunk = this.chunks.get(key);
461:     if (chunk) chunk.dirty = true;
462:   }
463: 
464:   getChunk(cx, cy) {
465:     const key = `${cx},${cy}`;
466:     let entry = this.chunks.get(key);
467:     if (entry && !entry.dirty) return entry.canvas;
468:     if (!entry) {
469:       const canvas = document.createElement('canvas');
470:       canvas.width = TILE * 12;
471:       canvas.height = TILE * 12;
472:       entry = { canvas, dirty: true };
473:       if (this.chunks.size > 48) this.chunks.clear();
474:       this.chunks.set(key, entry);
475:     }
476:     const ctx = entry.canvas.getContext('2d');
477:     ctx.clearRect(0, 0, TILE * 12, TILE * 12);
478: 
479:     for (let ly = 0; ly < 12; ly++) {
480:       for (let lx = 0; lx < 12; lx++) {
481:         const tx = cx * 12 + lx, ty = cy * 12 + ly;
482:         if (!this.inBounds(tx, ty)) continue;
483:         this.drawTile(ctx, tx, ty, lx * TILE, ly * TILE);
484:       }
485:     }
486:     entry.dirty = false;
487:     return entry.canvas;
488:   }
489: 
490:   drawTile(ctx, tx, ty, px, py) {
491:     const t = this.terrain[this.idx(tx, ty)];
492:     const h = hash2(tx, ty, this.seed + 3);
493: 
494:     if (t === TER.GRASS || t === TER.FOREST) {
495:       const tufts = t === TER.FOREST ? 4 : 6;
496:       ctx.strokeStyle = t === TER.FOREST ? 'rgba(100,124,76,0.5)' : 'rgba(122,148,92,0.42)';
497:       ctx.lineWidth = 1.2;
498:       for (let i = 0; i < tufts; i++) {
499:         const hx = hash2(tx, ty, i * 17 + 4);
500:         const hy = hash2(tx, ty, i * 31 + 9);
501:         const gx = px + 2 + hx * (TILE - 4);
502:         const gy = py + 4 + hy * (TILE - 6);
503:         const lean = (hx - 0.5) * 4;
504:         ctx.beginPath();
505:         ctx.moveTo(gx, gy);
506:         ctx.lineTo(gx + lean, gy - 4 - hy * 3);
507:         ctx.stroke();
508:         if (i === 0 && h > 0.5) {
509:           ctx.beginPath();
510:           ctx.moveTo(gx + 2, gy);
511:           ctx.lineTo(gx + 4 + lean, gy - 3);
512:           ctx.stroke();
513:         }
514:       }
515:       if (t === TER.FOREST && h > 0.35) {
516:         ctx.fillStyle = 'rgba(23,30,18,0.5)';
517:         ctx.beginPath();
518:         ctx.ellipse(px + 10 + h * 24, py + 14 + h * 20, 5, 3, h, 0, TAU);
519:         ctx.fill();
520:       }
521:       if (t === TER.FOREST && h > 0.86) {
522:         ctx.fillStyle = 'rgba(134,152,102,0.35)';
523:         for (let i = 0; i < 4; i++) {
524:           ctx.fillRect(px + 8 + hash2(tx, ty, 60 + i) * 32, py + 8 + hash2(tx, ty, 70 + i) * 32, 1.5, 1.5);
525:         }
526:       }
527:       if (h > 0.72) {
528:         const fx = px + 6 + hash2(tx, ty, 90) * 36;
529:         const fy = py + 6 + hash2(tx, ty, 91) * 36;
530:         ctx.fillStyle = hash2(tx, ty, 92) > 0.6 ? 'rgba(224, 214, 176, 0.55)' : 'rgba(200, 176, 90, 0.5)';
531:         ctx.fillRect(fx, fy, 1.6, 1.6);
532:       }
533:     } else if (t === TER.SAND) {
534:       ctx.fillStyle = 'rgba(45, 40, 28, 0.35)';
535:       for (let i = 0; i < 3; i++) {
536:         const gx = px + hash2(tx, ty, 20 + i) * TILE;
537:         const gy = py + hash2(tx, ty, 30 + i) * TILE;
538:         ctx.fillRect(gx, gy, 2, 1);
539:       }
540:     } else if (t === TER.ROCK) {
541:       ctx.strokeStyle = 'rgba(25, 25, 22, 0.45)';
542:       ctx.lineWidth = 1;
543:       ctx.beginPath();
544:       const sx = px + 8 + h * 20, sy = py + 6 + h * 10;
545:       ctx.moveTo(sx, sy);
546:       ctx.lineTo(sx + 8, sy + 14);
547:       ctx.lineTo(sx + 4, sy + 24);
548:       ctx.stroke();
549:       ctx.fillStyle = 'rgba(255,255,255,0.045)';
550:       ctx.beginPath();
551:       ctx.ellipse(px + 28, py + 18, 9, 5, -0.5, 0, TAU);
552:       ctx.fill();
553:     } else if (t === TER.WATER) {
554:       ctx.fillStyle = 'rgba(96, 148, 148, 0.05)';
555:       ctx.fillRect(px, py, TILE, TILE);
556:       ctx.strokeStyle = 'rgba(150, 196, 192, 0.12)';
557:       ctx.lineWidth = 1;
558:       ctx.beginPath();
559:       ctx.moveTo(px + 6, py + 16 + h * 12);
560:       ctx.quadraticCurveTo(px + 18, py + 12 + h * 12, px + 30, py + 17 + h * 12);
561:       ctx.stroke();
562:     } else if (t === TER.ASH) {
563:       ctx.fillStyle = 'rgba(12, 11, 10, 0.35)';
564:       ctx.beginPath();
565:       ctx.ellipse(px + 20 + h * 10, py + 20 + h * 8, 9, 5, h * 2, 0, TAU);
566:       ctx.fill();
567:       ctx.fillStyle = 'rgba(140, 120, 100, 0.18)';
568:       ctx.fillRect(px + 8 + h * 26, py + 10 + h * 20, 1.5, 1.5);
569:     }
570:   }
571: 
572:   drawGround(ctx, view, w, h, time) {
573:     const ox = view.x;
574:     const oy = view.y;
575:     if (this.terrainBase) {
576:       const scale = WORLD_SIZE / this.terrainBase.width;
577:       const sx = clamp(ox / scale, 0, this.terrainBase.width);
578:       const sy = clamp(oy / scale, 0, this.terrainBase.height);
579:       const sw = Math.min(this.terrainBase.width - sx, w / scale);
580:       const sh = Math.min(this.terrainBase.height - sy, h / scale);
581:       const dx = sx * scale - ox;
582:       const dy = sy * scale - oy;
583:       ctx.imageSmoothingEnabled = true;
584:       ctx.imageSmoothingQuality = 'high';
585:       ctx.drawImage(this.terrainBase, sx, sy, sw, sh, dx, dy, sw * scale, sh * scale);
586:     }
587: 
588:     const c0x = Math.floor(ox / (TILE * 12)) - 1;
589:     const c1x = Math.floor((ox + w) / (TILE * 12)) + 1;
590:     const c0y = Math.floor(oy / (TILE * 12)) - 1;
591:     const c1y = Math.floor((oy + h) / (TILE * 12)) + 1;
592:     for (let cy = c0y; cy <= c1y; cy++) {
593:       for (let cx = c0x; cx <= c1x; cx++) {
594:         const chunk = this.getChunk(cx, cy);
595:         ctx.drawImage(chunk, cx * TILE * 12 - ox, cy * TILE * 12 - oy);
596:       }
597:     }
598: 
599:     // continuous ground mottling breaks up the tile grid
600:     if (this.groundNoise) {
601:       const n = this.groundNoise.width;
602:       const scale = WORLD_SIZE / n;
603:       const sx = clamp(ox / scale, 0, n);
604:       const sy = clamp(oy / scale, 0, n);
605:       const sw = Math.min(n - sx, w / scale);
606:       const sh = Math.min(n - sy, h / scale);
607:       const dx = sx * scale - ox;
608:       const dy = sy * scale - oy;
609:       ctx.save();
610:       ctx.globalCompositeOperation = 'overlay';
611:       ctx.globalAlpha = 0.4;
612:       ctx.imageSmoothingEnabled = true;
613:       ctx.drawImage(this.groundNoise, sx, sy, sw, sh, dx, dy, sw * scale, sh * scale);
614:       ctx.restore();
615:     }
616: 
617:     // camp clearing
618:     const campX = this.camp.x - ox;
619:     const campY = this.camp.y - oy;
620:     if (campX > -420 && campX < w + 420 && campY > -420 && campY < h + 420) {
621:       const cg = ctx.createRadialGradient(campX, campY + 20, 20, campX, campY + 20, 250);
622:       cg.addColorStop(0, 'rgba(88, 73, 48, 0.24)');
623:       cg.addColorStop(0.55, 'rgba(78, 66, 45, 0.14)');
624:       cg.addColorStop(1, 'rgba(76, 64, 44, 0)');
625:       ctx.fillStyle = cg;
626:       ctx.beginPath();
627:       ctx.ellipse(campX, campY + 20, 250, 180, 0, 0, TAU);
628:       ctx.fill();
629:       ctx.fillStyle = 'rgba(60, 51, 35, 0.12)';
630:       ctx.beginPath();
631:       ctx.ellipse(campX, campY + 110, 44, 160, 0, 0, TAU);
632:       ctx.fill();
633:     }
634: 
635:     // animated water highlights
636:     const tx0 = Math.max(0, Math.floor(ox / TILE));
637:     const ty0 = Math.max(0, Math.floor(oy / TILE));
638:     const tx1 = Math.min(this.size - 1, Math.ceil((ox + w) / TILE));
